/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["adm"]=g.BC_LEI_REVISAO["adm"]||{};g.BC_LEI_REVISAO["adm"][19]=[{"key":"cf:5","law":"cf","ref":"5","label":"Constituição Federal · CF/88 · Art. 5","paragraphs":["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","I - homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição;","II - ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei;","III - ninguém será submetido a tortura nem a tratamento desumano ou degradante;","IV - é livre a manifestação do pensamento, sendo vedado o anonimato;","V - é assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou à imagem;","VI - é inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias;","VII - é assegurada, nos termos da lei, a prestação de assistência religiosa nas entidades civis e militares de internação coletiva;","VIII - ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e recusar-se a cumprir prestação alternativa, fixada em lei;","IX - é livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de censura ou licença;","X - são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação;","XI - a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial;","XII - é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;","XIII - é livre o exercício de qualquer trabalho, ofício ou profissão, atendidas as qualificações profissionais que a lei estabelecer;","XIV - é assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional;","XV - é livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus bens;","XVI - todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;","XVII - é plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar;","XVIII - a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento;","XIX - as associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado;","XX - ninguém poderá ser compelido a associar-se ou a permanecer associado;","XXI - as entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados judicial ou extrajudicialmente;","XXII - é garantido o direito de propriedade;","XXIII - a propriedade atenderá a sua função social;","XXIV - a lei estabelecerá o procedimento para desapropriação por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos nesta Constituição;","XXV - no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano;","XXVI - a pequena propriedade rural, assim definida em lei, desde que trabalhada pela família, não será objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, dispondo a lei sobre os meios de financiar o seu desenvolvimento;","XXVII - aos autores pertence o direito exclusivo de utilização, publicação ou reprodução de suas obras, transmissível aos herdeiros pelo tempo que a lei fixar;","XXVIII - são assegurados, nos termos da lei:","a) a proteção às participações individuais em obras coletivas e à reprodução da imagem e voz humanas, inclusive nas atividades desportivas;","b) o direito de fiscalização do aproveitamento econômico das obras que criarem ou de que participarem aos criadores, aos intérpretes e às respectivas representações sindicais e associativas;","XXIX - a lei assegurará aos autores de inventos industriais privilégio temporário para sua utilização, bem como proteção às criações industriais, à propriedade das marcas, aos nomes de empresas e a outros signos distintivos, tendo em vista o interesse social e o desenvolvimento tecnológico e econômico do País;","XXX - é garantido o direito de herança;","XXXI - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do de cujus;","XXXII - o Estado promoverá, na forma da lei, a defesa do consumidor;","XXXIII - todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, que serão prestadas no prazo da lei, sob pena de responsabilidade, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado;","XXXIV - são a todos assegurados, independentemente do pagamento de taxas:","a) o direito de petição aos poderes públicos em defesa de direitos ou contra ilegalidade ou abuso de poder;","b) a obtenção de certidões em repartições públicas, para defesa de direitos e esclarecimento de situações de interesse pessoal;","XXXV - a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;","XXXVI - a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;","XXXVII - não haverá juízo ou tribunal de exceção;","XXXVIII - é reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados:","a) a plenitude de defesa;","b) o sigilo das votações;","c) a soberania dos veredictos;","d) a competência para o julgamento dos crimes dolosos contra a vida;","XXXIX - não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal;","XL - a lei penal não retroagirá, salvo para beneficiar o réu;","XLI - a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;","XLII - a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;","XLIII - a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem;","XLIV - constitui crime inafiançável e imprescritível a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado democrático;","XLV - nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser, nos termos da lei, estendidas aos sucessores e contra eles executadas, até o limite do valor do patrimônio transferido;","XLVI - a lei regulará a individualização da pena e adotará, entre outras, as seguintes:","a) privação ou restrição da liberdade;","b) perda de bens;","c) multa;","d) prestação social alternativa;","e) suspensão ou interdição de direitos;","XLVII - não haverá penas:","a) de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX;","b) de caráter perpétuo;","c) de trabalhos forçados;","d) de banimento;","e) cruéis;","XLVIII - a pena será cumprida em estabelecimentos distintos, de acordo com a natureza do delito, a idade e o sexo do apenado;","XLIX - é assegurado aos presos o respeito à integridade física e moral;","L - às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação;","LI - nenhum brasileiro será extraditado, salvo o naturalizado, em caso de crime comum, praticado antes da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei;","LII - não será concedida extradição de estrangeiro por crime político ou de opinião;","LIII - ninguém será processado nem sentenciado senão pela autoridade competente;","LIV - ninguém será privado da liberdade ou de seus bens sem o devido processo legal;","LV - aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e a ampla defesa, com os meios e recursos a ela inerentes;","LVI - são inadmissíveis, no processo, as provas obtidas por meios ilícitos;","LVII - ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;","LVIII - o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei;","LIX - será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal;","LX - a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem;","LXI - ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;","LXII - a prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada;","LXIII - o preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado;","LXIV - o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial;","LXV - a prisão ilegal será imediatamente relaxada pela autoridade judiciária;","LXVI - ninguém será levado à prisão ou nela mantido quando a lei admitir a liberdade provisória, com ou sem fiança;","LXVII - não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;","LXVIII - conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder;","LXIX - conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública ou agente de pessoa jurídica no exercício de atribuições do poder público;","LXX - o mandado de segurança coletivo pode ser impetrado por:","a) partido político com representação no Congresso Nacional;","b) organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados;","LXXI - conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania;","LXXII - conceder-se-á habeas data:","a) para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público;","b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo;","LXXIII - qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, salvo comprovada má-fé, isento de custas judiciais e do ônus da sucumbência;","LXXIV - o Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos;","LXXV - o Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na sentença;","LXXVI - são gratuitos para os reconhecidamente pobres, na forma da lei:","a) o registro civil de nascimento;","b) a certidão de óbito;","LXXVII - são gratuitas as ações de habeas corpus e habeas data, e, na forma da lei, os atos necessários ao exercício da cidadania.","LXXVIII - a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação. (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","LXXIX - é assegurado, nos termos da lei, o direito à proteção dos dados pessoais, inclusive nos meios digitais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","§ 1º As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.","§ 2º Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte.","§ 3º Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)","§ 4º O Brasil se submete à jurisdição de Tribunal Penal Internacional a cuja criação tenha manifestado adesão. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":""},{"key":"cf:37","law":"cf","ref":"37","label":"Constituição Federal · CF/88 · Art. 37","paragraphs":["Art. 37. A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte: (“Caput” do artigo com redação dada pela Emenda Constitucional nº 19, de 1998)","I - os cargos, empregos e funções públicas são acessíveis aos brasileiros que preencham os requisitos estabelecidos em lei, assim como aos estrangeiros, na forma da lei; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","II - a investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, de acordo com a natureza e a complexidade do cargo ou emprego, na forma prevista em lei, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","III - o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por igual período;","IV - durante o prazo improrrogável previsto no edital de convocação, aquele aprovado em concurso público de provas ou de provas e títulos será convocado com prioridade sobre novos concursados para assumir cargo ou emprego, na carreira;","V - as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão, a serem preenchidos por servidores de carreira nos casos, condições e percentuais mínimos previstos em lei, destinam-se apenas às atribuições de direção, chefia e assessoramento; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VI - é garantido ao servidor público civil o direito à livre associação sindical;","VII - o direito de greve será exercido nos termos e nos limites definidos em lei específica; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VIII - a lei reservará percentual dos cargos e empregos públicos para as pessoas portadoras de deficiência e definirá os critérios de sua admissão;","IX - a lei estabelecerá os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;","X - a remuneração dos servidores públicos e o subsídio de que trata o § 4º do art. 39 somente poderão ser fixados ou alterados por lei específica, observada a iniciativa privativa em cada caso, assegurada revisão geral anual, sempre na mesma data e sem distinção de índices; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XI - a remuneração e o subsídio dos ocupantes de cargos, funções e empregos públicos da administração direta, autárquica e fundacional, dos membros de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, dos detentores de mandato eletivo e dos demais agentes políticos e os proventos, pensões ou outra espécie remuneratória, percebidos cumulativamente ou não, incluídas as vantagens pessoais ou de qualquer outra natureza, não poderão exceder o subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, aplicando-se como limite, nos Municípios, o subsídio do Prefeito, e nos Estados e no Distrito Federal, o subsídio mensal do Governador no âmbito do Poder Executivo, o subsídio dos Deputados Estaduais e Distritais no âmbito do Poder Legislativo e o subsídio dos Desembargadores do Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, no âmbito do Poder Judiciário, aplicável este limite aos membros do Ministério Público, aos Procuradores e aos Defensores Públicos; (Inciso com redação dada pela Emenda Constitucional nº 41, de 2003)","XII - os vencimentos dos cargos do Poder Legislativo e do Poder Judiciário não poderão ser superiores aos pagos pelo Poder Executivo;","XIII - é vedada a vinculação ou equiparação de quaisquer espécies remuneratórias para o efeito de remuneração de pessoal do serviço público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XIV - os acréscimos pecuniários percebidos por servidor público não serão computados nem acumulados para fins de concessão de acréscimos ulteriores; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XV - o subsídio e os vencimentos dos ocupantes de cargos e empregos públicos são irredutíveis, ressalvado o disposto nos incisos XI e XIV deste artigo e nos arts. 39, § 4º, 150, II, 153, III, e 153, § 2º, I; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVI - é vedada a acumulação remunerada de cargos públicos, exceto, quando houver compatibilidade de horários, observado em qualquer caso o disposto no inciso XI: (“Caput” do inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","a) a de dois cargos de professor;","b) a de um cargo de professor com outro de qualquer natureza; (Alínea com redação dada pela Emenda Constitucional nº 138, de 2025)","c) a de dois cargos ou empregos privativos de profissionais de saúde, com profissões regulamentadas; (Alínea com redação dada pela Emenda Constitucional nº 34, de 2001)","XVII - a proibição de acumular estende-se a empregos e funções e abrange autarquias, fundações, empresas públicas, sociedades de economia mista, suas subsidiárias, e sociedades controladas, direta ou indiretamente, pelo poder público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVIII - a administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma da lei;","XIX - somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, de sociedade de economia mista e de fundação, cabendo à lei complementar, neste último caso, definir as áreas de sua atuação; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XX - depende de autorização legislativa, em cada caso, a criação de subsidiárias das entidades mencionadas no inciso anterior, assim como a participação de qualquer delas em empresa privada;","XXI - ressalvados os casos especificados na legislação, as obras, serviços, compras e alienações serão contratados mediante processo de licitação pública que assegure igualdade de condições a todos os concorrentes, com cláusulas que estabeleçam obrigações de pagamento, mantidas as condições efetivas da proposta, nos termos da lei, o qual somente permitirá as exigências de qualificação técnica e econômica indispensáveis à garantia do cumprimento das obrigações.","XXII - as administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, exercidas por servidores de carreiras específicas, terão recursos prioritários para a realização de suas atividades e atuarão de forma integrada, inclusive com o compartilhamento de cadastros e de informações fiscais, na forma da lei ou convênio. (Inciso acrescido pela Emenda Constitucional nº 42, de 2003)","§ 1º A publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deverá ter caráter educativo, informativo ou de orientação social, dela não podendo constar nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos.","§ 2º A não-observância do disposto nos incisos II e III implicará a nulidade do ato e a punição da autoridade responsável, nos termos da lei.","§ 3º A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente:","I - as reclamações relativas à prestação dos serviços públicos em geral, asseguradas a manutenção de serviços de atendimento ao usuário e a avaliação periódica, externa e interna, da qualidade dos serviços;","II - o acesso dos usuários a registros administrativos e a informações sobre atos de governo, observado o disposto no art. 5º, X e XXXIII;","III - a disciplina da representação contra o exercício negligente ou abusivo de cargo, emprego ou função na administração pública. (Parágrafo com redação dada pela Emenda Constitucional nº 19, de 1998)","§ 4º Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","§ 5º A lei estabelecerá os prazos de prescrição para ilícitos praticados por qualquer agente, servidor ou não, que causem prejuízos ao erário, ressalvadas as respectivas ações de ressarcimento.","§ 6º As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.","§ 7º A lei disporá sobre os requisitos e as restrições ao ocupante de cargo ou emprego da administração direta e indireta que possibilite o acesso a informações privilegiadas. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 8º A autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta poderá ser ampliada mediante contrato, a ser firmado entre seus administradores e o poder público, que tenha por objeto a fixação de metas de desempenho para o órgão ou entidade, cabendo à lei dispor sobre:","I - o prazo de duração do contrato;","II - os controles e critérios de avaliação de desempenho, direitos, obrigações e responsabilidade dos dirigentes;","III - a remuneração do pessoal. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 9º O disposto no inciso XI aplica-se às empresas públicas e às sociedades de economia mista, e suas subsidiárias, que receberem recursos da União, dos Estados, do Distrito Federal ou dos Municípios para pagamento de despesas de pessoal ou de custeio em geral. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 10. É vedada a percepção simultânea de proventos de aposentadoria decorrentes do art. 40 ou dos arts. 42 e 142 com a remuneração de cargo, emprego ou função pública, ressalvados os cargos acumuláveis na forma desta Constituição, os cargos eletivos e os cargos em comissão declarados em lei de livre nomeação e exoneração. (Parágrafo acrescido pela Emenda Constitucional nº 20, de 1998)","§ 11. Não serão computadas, para efeito dos limites remuneratórios de que trata o inciso XI do caput deste artigo, as parcelas de caráter indenizatório expressamente previstas em lei ordinária, aprovada pelo Congresso Nacional, de caráter nacional, aplicada a todos os Poderes e órgãos constitucionalmente autônomos. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005, e com redação dada pela Emenda Constitucional nº 135, de 2024)","§ 12. Para os fins do disposto no inciso XI do caput deste artigo, fica facultado aos Estados e ao Distrito Federal fixar, em seu âmbito, mediante emenda às respectivas Constituições e Lei Orgânica, como limite único, o subsídio mensal dos Desembargadores do respectivo Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal dos Ministros do Supremo Tribunal Federal, não se aplicando o disposto neste parágrafo aos subsídios dos Deputados Estaduais e Distritais e dos Vereadores. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005)","§ 13. O servidor público titular de cargo efetivo poderá ser readaptado para exercício de cargo cujas atribuições e responsabilidades sejam compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental, enquanto permanecer nesta condição, desde que possua a habilitação e o nível de escolaridade exigidos para o cargo de destino, mantida a remuneração do cargo de origem. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 14. A aposentadoria concedida com a utilização de tempo de contribuição decorrente de cargo, emprego ou função pública, inclusive do Regime Geral de Previdência Social, acarretará o rompimento do vínculo que gerou o referido tempo de contribuição. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 15. É vedada a complementação de aposentadorias de servidores públicos e de pensões por morte a seus dependentes que não seja decorrente do disposto nos §§ 14 a 16 do art. 40 ou que não seja prevista em lei que extinga regime próprio de previdência social. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 16. Os órgãos e entidades da administração pública, individual ou conjuntamente, devem realizar avaliação das políticas públicas, inclusive com divulgação do objeto a ser avaliado e dos resultados alcançados, na forma da lei. (Parágrafo acrescido pela Emenda Constitucional nº 109, de 2021)","§ 17. (Vide Emenda Constitucional nº 132, de 2023)","§ 18. (Vide Emenda Constitucional nº 132, de 2023)"],"url":""},{"key":"cf:216","law":"cf","ref":"216","label":"Constituição Federal · CF/88 · Art. 216","paragraphs":["Art. 216. Constituem patrimônio cultural brasileiro os bens de natureza material e imaterial, tomados individualmente ou em conjunto, portadores de referência à identidade, à ação, à memória dos diferentes grupos formadores da sociedade brasileira, nos quais se incluem:","I - as formas de expressão;","II - os modos de criar, fazer e viver;","III - as criações científicas, artísticas e tecnológicas;","IV - as obras, objetos, documentos, edificações e demais espaços destinados às manifestações artístico-culturais;","V - os conjuntos urbanos e sítios de valor histórico, paisagístico, artístico, arqueológico, paleontológico, ecológico e científico.","§ 1º O poder público, com a colaboração da comunidade, promoverá e protegerá o patrimônio cultural brasileiro, por meio de inventários, registros, vigilância, tombamento e desapropriação, e de outras formas de acautelamento e preservação.","§ 2º Cabem à administração pública, na forma da lei, a gestão da documentação governamental e as providências para franquear sua consulta a quantos dela necessitem.","§ 3º A lei estabelecerá incentivos para a produção e o conhecimento de bens e valores culturais.","§ 4º Os danos e ameaças ao patrimônio cultural serão punidos, na forma da lei.","§ 5º Ficam tombados todos os documentos e os sítios detentores de reminiscências históricas dos antigos quilombos.","§ 6º É facultado aos Estados e ao Distrito Federal vincular a fundo estadual de fomento à cultura até cinco décimos por cento de sua receita tributária líquida, para o financiamento de programas e projetos culturais, vedada a aplicação desses recursos no pagamento de:","I - despesas com pessoal e encargos sociais;","II - serviço da dívida;","III - qualquer outra despesa corrente não vinculada diretamente aos investimentos ou ações apoiados. (Parágrafo acrescido pela Emenda Constitucional nº 42, de 2003)"],"url":""},{"key":"l12527:3","law":"l12527","ref":"3","label":"Lei de Acesso à Informação · Art. 3","paragraphs":["Art. 3º Os procedimentos previstos nesta Lei destinam-se a assegurar o direito fundamental de acesso à informação e devem ser executados em conformidade com os princípios básicos da administração pública e com as seguintes diretrizes:","I - observância da publicidade como preceito geral e do sigilo como exceção;","II - divulgação de informações de interesse público, independentemente de solicitações;","III - utilização de meios de comunicação viabilizados pela tecnologia da informação;","IV - fomento ao desenvolvimento da cultura de transparência na administração pública;","V - desenvolvimento do controle social da administração pública."],"url":""},{"key":"l12527:1","law":"l12527","ref":"1","label":"Lei de Acesso à Informação · Art. 1","paragraphs":["Art. 1º Esta Lei dispõe sobre os procedimentos a serem observados pela União, Estados, Distrito Federal e Municípios, com o fim de garantir o acesso a informações previsto no inciso XXXIII do art. 5º, no inciso II do § 3º do art. 37 e no § 2º do art. 216 da Constituição Federal.","Parágrafo único. Subordinam-se ao regime desta Lei:","I - os órgãos públicos integrantes da administração direta dos Poderes Executivo, Legislativo, incluindo as Cortes de Contas, e Judiciário e do Ministério Público;","II - as autarquias, as fundações públicas, as empresas públicas, as sociedades de economia mista e demais entidades controladas direta ou indiretamente pela União, Estados, Distrito Federal e Municípios."],"url":""},{"key":"l12527:2","law":"l12527","ref":"2","label":"Lei de Acesso à Informação · Art. 2","paragraphs":["Art. 2º Aplicam-se as disposições desta Lei, no que couber, às entidades privadas sem fins lucrativos que recebam, para realização de ações de interesse público, recursos públicos diretamente do orçamento ou mediante subvenções sociais, contrato de gestão, termo de parceria, convênios, acordo, ajustes ou outros instrumentos congêneres.","Parágrafo único. A publicidade a que estão submetidas as entidades citadas no caput refere-se à parcela dos recursos públicos recebidos e à sua destinação, sem prejuízo das prestações de contas a que estejam legalmente obrigadas."],"url":""},{"key":"l12527:4","law":"l12527","ref":"4","label":"Lei de Acesso à Informação · Art. 4","paragraphs":["Art. 4º Para os efeitos desta Lei, considera-se:","I - informação: dados, processados ou não, que podem ser utilizados para produção e transmissão de conhecimento, contidos em qualquer meio, suporte ou formato;","II - documento: unidade de registro de informações, qualquer que seja o suporte ou formato;","III - informação sigilosa: aquela submetida temporariamente à restrição de acesso público em razão de sua imprescindibilidade para a segurança da sociedade e do Estado;","IV - informação pessoal: aquela relacionada à pessoa natural identificada ou identificável;","V - tratamento da informação: conjunto de ações referentes à produção, recepção, classificação, utilização, acesso, reprodução, transporte, transmissão, distribuição, arquivamento, armazenamento, eliminação, avaliação, destinação ou controle da informação;","VI - disponibilidade: qualidade da informação que pode ser conhecida e utilizada por indivíduos, equipamentos ou sistemas autorizados;","VII - autenticidade: qualidade da informação que tenha sido produzida, expedida, recebida ou modificada por determinado indivíduo, equipamento ou sistema;","VIII - integridade: qualidade da informação não modificada, inclusive quanto à origem, trânsito e destino;","IX - primariedade: qualidade da informação coletada na fonte, com o máximo de detalhamento possível, sem modificações."],"url":""},{"key":"l12527:31","law":"l12527","ref":"31","label":"Lei de Acesso à Informação · Art. 31","paragraphs":["Art. 31. O tratamento das informações pessoais deve ser feito de forma transparente e com respeito à intimidade, vida privada, honra e imagem das pessoas, bem como às liberdades e garantias individuais.","§ 1º As informações pessoais, a que se refere este artigo, relativas à intimidade, vida privada, honra e imagem:","I - terão seu acesso restrito, independentemente de classificação de sigilo e pelo prazo máximo de 100 (cem) anos a contar da sua data de produção, a agentes públicos legalmente autorizados e à pessoa a que elas se referirem; e","II - poderão ter autorizada sua divulgação ou acesso por terceiros diante de previsão legal ou consentimento expresso da pessoa a que elas se referirem.","§ 2º Aquele que obtiver acesso às informações de que trata este artigo será responsabilizado por seu uso indevido.","§ 3º O consentimento referido no inciso II do § 1º não será exigido quando as informações forem necessárias:","I - à prevenção e diagnóstico médico, quando a pessoa estiver física ou legalmente incapaz, e para utilização única e exclusivamente para o tratamento médico;","II - à realização de estatísticas e pesquisas científicas de evidente interesse público ou geral, previstos em lei, sendo vedada a identificação da pessoa a que as informações se referirem;","III - ao cumprimento de ordem judicial;","IV - à defesa de direitos humanos; ou","V - à proteção do interesse público e geral preponderante.","§ 4º A restrição de acesso à informação relativa à vida privada, honra e imagem de pessoa não poderá ser invocada com o intuito de prejudicar processo de apuração de irregularidades em que o titular das informações estiver envolvido, bem como em ações voltadas para a recuperação de fatos históricos de maior relevância.","§ 5º Regulamento disporá sobre os procedimentos para tratamento de informação pessoal."],"url":""},{"key":"l12527:23","law":"l12527","ref":"23","label":"Lei de Acesso à Informação · Art. 23","paragraphs":["Art. 23. São consideradas imprescindíveis à segurança da sociedade ou do Estado e, portanto, passíveis de classificação as informações cuja divulgação ou acesso irrestrito possam:","I - pôr em risco a defesa e a soberania nacionais ou a integridade do território nacional;","II - prejudicar ou pôr em risco a condução de negociações ou as relações internacionais do País, ou as que tenham sido fornecidas em caráter sigiloso por outros Estados e organismos internacionais;","III - pôr em risco a vida, a segurança ou a saúde da população;","IV - oferecer elevado risco à estabilidade financeira, econômica ou monetária do País;","V - prejudicar ou causar risco a planos ou operações estratégicos das Forças Armadas;","VI - prejudicar ou causar risco a projetos de pesquisa e desenvolvimento científico ou tecnológico, assim como a sistemas, bens, instalações ou áreas de interesse estratégico nacional;","VII - pôr em risco a segurança de instituições ou de altas autoridades nacionais ou estrangeiras e seus familiares; ou","VIII - comprometer atividades de inteligência, bem como de investigação ou fiscalização em andamento, relacionadas com a prevenção ou repressão de infrações."],"url":""},{"key":"l12527:8","law":"l12527","ref":"8","label":"Lei de Acesso à Informação · Art. 8","paragraphs":["Art. 8º É dever dos órgãos e entidades públicas promover, independentemente de requerimentos, a divulgação em local de fácil acesso, no âmbito de suas competências, de informações de interesse coletivo ou geral por eles produzidas ou custodiadas.","§ 1º Na divulgação das informações a que se refere o caput, deverão constar, no mínimo:","I - registro das competências e estrutura organizacional, endereços e telefones das respectivas unidades e horários de atendimento ao público;","II - registros de quaisquer repasses ou transferências de recursos financeiros;","III - registros das despesas;","IV - informações concernentes a procedimentos licitatórios, inclusive os respectivos editais e resultados, bem como a todos os contratos celebrados;","V - dados gerais para o acompanhamento de programas, ações, projetos e obras de órgãos e entidades; e","VI - respostas a perguntas mais frequentes da sociedade.","§ 2º Para cumprimento do disposto no caput, os órgãos e entidades públicas deverão utilizar todos os meios e instrumentos legítimos de que dispuserem, sendo obrigatória a divulgação em sítios oficiais da rede mundial de computadores (internet).","§ 3º Os sítios de que trata o § 2º deverão, na forma de regulamento, atender, entre outros, aos seguintes requisitos:","I - conter ferramenta de pesquisa de conteúdo que permita o acesso à informação de forma objetiva, transparente, clara e em linguagem de fácil compreensão;","II - possibilitar a gravação de relatórios em diversos formatos eletrônicos, inclusive abertos e não proprietários, tais como planilhas e texto, de modo a facilitar a análise das informações;","III - possibilitar o acesso automatizado por sistemas externos em formatos abertos, estruturados e legíveis por máquina;","IV - divulgar em detalhes os formatos utilizados para estruturação da informação;","V - garantir a autenticidade e a integridade das informações disponíveis para acesso;","VI - manter atualizadas as informações disponíveis para acesso;","VII - indicar local e instruções que permitam ao interessado comunicar-se, por via eletrônica ou telefônica, com o órgão ou entidade detentora do sítio; e","VIII - adotar as medidas necessárias para garantir a acessibilidade de conteúdo para pessoas com deficiência, nos termos do art. 17 da Lei nº 10.098, de 19 de dezembro de 2000, e do art. 9º da Convenção sobre os Direitos das Pessoas com Deficiência, aprovada pelo Decreto Legislativo nº 186, de 9 de julho de 2008.","§ 4º Os Municípios com população de até 10.000 (dez mil) habitantes ficam dispensados da divulgação obrigatória na internet a que se refere o § 2º, mantida a obrigatoriedade de divulgação, em tempo real, de informações relativas à execução orçamentária e financeira, nos critérios e prazos previstos no art. 73-B da Lei Complementar nº 101, de 4 de maio de 2000 (Lei de Responsabilidade Fiscal)."],"url":""},{"key":"l12527:8-A","law":"l12527","ref":"8-A","label":"Lei de Acesso à Informação · Art. 8-A","paragraphs":["Art. 8º-A. As entidades com personalidade jurídica de direito privado, constituídas sob a forma de serviço social autônomo, que sejam destinatárias de contribuições ou de recursos públicos federais decorrentes de contrato de gestão deverão divulgar as seguintes informações relativas aos respectivos empregados:","I - o plano de cargos e salários, inclusive com a divulgação dos critérios para a evolução na carreira e para a fixação da política salarial;","II - o quantitativo total de empregados da entidade, discriminado por cargo e por faixas salariais, acompanhado do nome do empregado e do cargo por ele ocupado;","III - lista, discriminada por faixas salariais, das parcelas remuneratórias e indenizatórias, ainda que eventuais, incluídos os auxílios, as ajudas de custo, as gratificações, os jetons e quaisquer outras vantagens pecuniárias, que os empregados possam receber em virtude de condições específicas; e","IV - o quantitativo de funções gratificadas, os critérios para sua ocupação e o rol dos empregados que ocupam cada espécie de função gratificada. (Artigo acrescido pela Lei nº 15.141, de 2/6/2025)"],"url":""},{"key":"l12527:8-B","law":"l12527","ref":"8-B","label":"Lei de Acesso à Informação · Art. 8-B","paragraphs":["Art. 8º-B. Os conselhos de fiscalização profissional devem divulgar, de forma nominal e individualizada, lista das parcelas remuneratórias e indenizatórias, ainda que eventuais, incluídos os auxílios, as ajudas de custo, as gratificações, os jetons e quaisquer outras vantagens pecuniárias, que os empregados possam receber em virtude de condições específicas. (Artigo acrescido pela Lei nº 15.141, de 2/6/2025)"],"url":""},{"key":"l12527:9","law":"l12527","ref":"9","label":"Lei de Acesso à Informação · Art. 9","paragraphs":["Art. 9º O acesso a informações públicas será assegurado mediante:","I - criação de serviço de informações ao cidadão, nos órgãos e entidades do poder público, em local com condições apropriadas para:","a) atender e orientar o público quanto ao acesso a informações;","b) informar sobre a tramitação de documentos nas suas respectivas unidades;","c) protocolizar documentos e requerimentos de acesso a informações; e","II - realização de audiências ou consultas públicas, incentivo à participação popular ou a outras formas de divulgação."],"url":""},{"key":"l12527:20","law":"l12527","ref":"20","label":"Lei de Acesso à Informação · Art. 20","paragraphs":["Art. 20. Aplica-se subsidiariamente, no que couber, a Lei nº 9.784, de 29 de janeiro de 1999, ao procedimento de que trata este Capítulo."],"url":""},{"key":"l12527:10","law":"l12527","ref":"10","label":"Lei de Acesso à Informação · Art. 10","paragraphs":["Art. 10. Qualquer interessado poderá apresentar pedido de acesso a informações aos órgãos e entidades referidos no art. 1º desta Lei, por qualquer meio legítimo, devendo o pedido conter a identificação do requerente e a especificação da informação requerida.","§ 1º Para o acesso a informações de interesse público, a identificação do requerente não pode conter exigências que inviabilizem a solicitação.","§ 2º Os órgãos e entidades do poder público devem viabilizar alternativa de encaminhamento de pedidos de acesso por meio de seus sítios oficiais na internet.","§ 3º São vedadas quaisquer exigências relativas aos motivos determinantes da solicitação de informações de interesse público."],"url":""},{"key":"l12527:11","law":"l12527","ref":"11","label":"Lei de Acesso à Informação · Art. 11","paragraphs":["Art. 11. O órgão ou entidade pública deverá autorizar ou conceder o acesso imediato à informação disponível.","§ 1º Não sendo possível conceder o acesso imediato, na forma disposta no caput, o órgão ou entidade que receber o pedido deverá, em prazo não superior a 20 (vinte) dias:","I - comunicar a data, local e modo para se realizar a consulta, efetuar a reprodução ou obter a certidão;","II - indicar as razões de fato ou de direito da recusa, total ou parcial, do acesso pretendido; ou","III - comunicar que não possui a informação, indicar, se for do seu conhecimento, o órgão ou a entidade que a detém, ou, ainda, remeter o requerimento a esse órgão ou entidade, cientificando o interessado da remessa de seu pedido de informação.","§ 2º O prazo referido no § 1º poderá ser prorrogado por mais 10 (dez) dias, mediante justificativa expressa, da qual será cientificado o requerente.","§ 3º Sem prejuízo da segurança e da proteção das informações e do cumprimento da legislação aplicável, o órgão ou entidade poderá oferecer meios para que o próprio requerente possa pesquisar a informação de que necessitar.","§ 4º Quando não for autorizado o acesso por se tratar de informação total ou parcialmente sigilosa, o requerente deverá ser informado sobre a possibilidade de recurso, prazos e condições para sua interposição, devendo, ainda, ser-lhe indicada a autoridade competente para sua apreciação.","§ 5º A informação armazenada em formato digital será fornecida nesse formato, caso haja anuência do requerente.","§ 6º Caso a informação solicitada esteja disponível ao público em formato impresso, eletrônico ou em qualquer outro meio de acesso universal, serão informados ao requerente, por escrito, o lugar e a forma pela qual se poderá consultar, obter ou reproduzir a referida informação, procedimento esse que desonerará o órgão ou entidade pública da obrigação de seu fornecimento direto, salvo se o requerente declarar não dispor de meios para realizar por si mesmo tais procedimentos."],"url":""},{"key":"l12527:12","law":"l12527","ref":"12","label":"Lei de Acesso à Informação · Art. 12","paragraphs":["Art. 12. O serviço de busca e de fornecimento de informação é gratuito. (“Caput” do artigo com redação dada pela Lei nº 14.129, de 29/3/2021, publicada no DOU de 30/3/2021, em vigor 90 dias após a publicação para a União; 120 dias após a publicação para os Estados e o Distrito Federal; e 180 dias após a publicação para os Municípios)","§ 1º O órgão ou a entidade poderá cobrar exclusivamente o valor necessário ao ressarcimento dos custos dos serviços e dos materiais utilizados, quando o serviço de busca e de fornecimento da informação exigir reprodução de documentos pelo órgão ou pela entidade pública consultada. (Parágrafo acrescido pela Lei nº 14.129, de 29/3/2021, publicada no DOU de 30/3/2021, em vigor 90 dias após a publicação para a União; 120 dias após a publicação para os Estados e o Distrito Federal; e 180 dias após a publicação para os Municípios)","§ 2º Estará isento de ressarcir os custos previstos no § 1º deste artigo aquele cuja situação econômica não lhe permita fazê-lo sem prejuízo do sustento próprio ou da família, declarada nos termos da Lei nº 7.115, de 29 de agosto de 1983. (Parágrafo único transformado em § 2º e com redação dada pela Lei nº 14.129, de 29/3/2021, publicada no DOU de 30/3/2021, em vigor 90 dias após a publicação para a União; 120 dias após a publicação para os Estados e o Distrito Federal; e 180 dias após a publicação para os Municípios)"],"url":""},{"key":"l12527:13","law":"l12527","ref":"13","label":"Lei de Acesso à Informação · Art. 13","paragraphs":["Art. 13. Quando se tratar de acesso à informação contida em documento cuja manipulação possa prejudicar sua integridade, deverá ser oferecida a consulta de cópia, com certificação de que esta confere com o original.","Parágrafo único. Na impossibilidade de obtenção de cópias, o interessado poderá solicitar que, a suas expensas e sob supervisão de servidor público, a reprodução seja feita por outro meio que não ponha em risco a conservação do documento original."],"url":""},{"key":"l12527:14","law":"l12527","ref":"14","label":"Lei de Acesso à Informação · Art. 14","paragraphs":["Art. 14. É direito do requerente obter o inteiro teor de decisão de negativa de acesso, por certidão ou cópia."],"url":""},{"key":"l12527:15","law":"l12527","ref":"15","label":"Lei de Acesso à Informação · Art. 15","paragraphs":["Art. 15. No caso de indeferimento de acesso a informações ou às razões da negativa do acesso, poderá o interessado interpor recurso contra a decisão no prazo de 10 (dez) dias a contar da sua ciência.","Parágrafo único. O recurso será dirigido à autoridade hierarquicamente superior à que exarou a decisão impugnada, que deverá se manifestar no prazo de 5 (cinco) dias."],"url":""},{"key":"l12527:16","law":"l12527","ref":"16","label":"Lei de Acesso à Informação · Art. 16","paragraphs":["Art. 16. Negado o acesso a informação pelos órgãos ou entidades do Poder Executivo Federal, o requerente poderá recorrer à Controladoria- Geral da União, que deliberará no prazo de 5 (cinco) dias se:","I - o acesso à informação não classificada como sigilosa for negado;","II - a decisão de negativa de acesso à informação total ou parcialmente classificada como sigilosa não indicar a autoridade classificadora ou a hierarquicamente superior a quem possa ser dirigido pedido de acesso ou desclassificação;","III - os procedimentos de classificação de informação sigilosa estabelecidos nesta Lei não tiverem sido observados; e","IV - estiverem sendo descumpridos prazos ou outros procedimentos previstos nesta Lei.","§ 1º O recurso previsto neste artigo somente poderá ser dirigido à Controladoria-Geral da União depois de submetido à apreciação de pelo menos uma autoridade hierarquicamente superior àquela que exarou a decisão impugnada, que deliberará no prazo de 5 (cinco) dias.","§ 2º Verificada a procedência das razões do recurso, a Controladoria-Geral da União determinará ao órgão ou entidade que adote as providências necessárias para dar cumprimento ao disposto nesta Lei.","§ 3º Negado o acesso à informação pela Controladoria-Geral da União, poderá ser interposto recurso à Comissão Mista de Reavaliação de Informações, a que se refere o art. 35."],"url":""},{"key":"l12527:17","law":"l12527","ref":"17","label":"Lei de Acesso à Informação · Art. 17","paragraphs":["Art. 17. No caso de indeferimento de pedido de desclassificação de informação protocolado em órgão da administração pública federal, poderá o requerente recorrer ao Ministro de Estado da área, sem prejuízo das competências da Comissão Mista de Reavaliação de Informações, previstas no art. 35, e do disposto no art. 16.","§ 1º O recurso previsto neste artigo somente poderá ser dirigido às autoridades mencionadas depois de submetido à apreciação de pelo menos uma autoridade hierarquicamente superior à autoridade que exarou a decisão impugnada e, no caso das Forças Armadas, ao respectivo Comando.","§ 2º Indeferido o recurso previsto no caput que tenha como objeto a desclassificação de informação secreta ou ultrassecreta, caberá recurso à Comissão Mista de Reavaliação de Informações prevista no art. 35."],"url":""},{"key":"l12527:18","law":"l12527","ref":"18","label":"Lei de Acesso à Informação · Art. 18","paragraphs":["Art. 18. Os procedimentos de revisão de decisões denegatórias proferidas no recurso previsto no art. 15 e de revisão de classificação de documentos sigilosos serão objeto de regulamentação própria dos Poderes Legislativo e Judiciário e do Ministério Público, em seus respectivos âmbitos, assegurado ao solicitante, em qualquer caso, o direito de ser informado sobre o andamento de seu pedido."],"url":""},{"key":"l12527:19","law":"l12527","ref":"19","label":"Lei de Acesso à Informação · Art. 19","paragraphs":["Art. 19. (VETADO).","§ 1º (VETADO).","§ 2º Os órgãos do Poder Judiciário e do Ministério Público informarão ao Conselho Nacional de Justiça e ao Conselho Nacional do Ministério Público, respectivamente, as decisões que, em grau de recurso, negarem acesso a informações de interesse público."],"url":""},{"key":"l12527:7","law":"l12527","ref":"7","label":"Lei de Acesso à Informação · Art. 7","paragraphs":["Art. 7º O acesso à informação de que trata esta Lei compreende, entre outros, os direitos de obter:","I - orientação sobre os procedimentos para a consecução de acesso, bem como sobre o local onde poderá ser encontrada ou obtida a informação almejada;","II - informação contida em registros ou documentos, produzidos ou acumulados por seus órgãos ou entidades, recolhidos ou não a arquivos públicos;","III - informação produzida ou custodiada por pessoa física ou entidade privada decorrente de qualquer vínculo com seus órgãos ou entidades, mesmo que esse vínculo já tenha cessado;","IV - informação primária, íntegra, autêntica e atualizada;","V - informação sobre atividades exercidas pelos órgãos e entidades, inclusive as relativas à sua política, organização e serviços;","VI - informação pertinente à administração do patrimônio público, utilização de recursos públicos, licitação, contratos administrativos; e","VII - informação relativa:","a) à implementação, acompanhamento e resultados dos programas, projetos e ações dos órgãos e entidades públicas, bem como metas e indicadores propostos;","b) ao resultado de inspeções, auditorias, prestações e tomadas de contas realizadas pelos órgãos de controle interno e externo, incluindo prestações de contas relativas a exercícios anteriores.","VIII - (VETADO na Lei nº 14.345, de 24/5/2022)","§ 1º O acesso à informação previsto no caput não compreende as informações referentes a projetos de pesquisa e desenvolvimento científicos ou tecnológicos cujo sigilo seja imprescindível à segurança da sociedade e do Estado.","§ 2º Quando não for autorizado acesso integral à informação por ser ela parcialmente sigilosa, é assegurado o acesso à parte não sigilosa por meio de certidão, extrato ou cópia com ocultação da parte sob sigilo.","§ 3º O direito de acesso aos documentos ou às informações neles contidas utilizados como fundamento da tomada de decisão e do ato administrativo será assegurado com a edição do ato decisório respectivo.","§ 4º A negativa de acesso às informações objeto de pedido formulado aos órgãos e entidades referidas no art. 1o, quando não fundamentada, sujeitará o responsável a medidas disciplinares, nos termos do art. 32 desta Lei.","§ 5º Informado do extravio da informação solicitada, poderá o interessado requerer à autoridade competente a imediata abertura de sindicância para apurar o desaparecimento da respectiva documentação.","§ 6º Verificada a hipótese prevista no § 5º deste artigo, o responsável pela guarda da informação extraviada deverá, no prazo de 10 (dez) dias, justificar o fato e indicar testemunhas que comprovem sua alegação."],"url":""},{"key":"l12527:33","law":"l12527","ref":"33","label":"Lei de Acesso à Informação · Art. 33","paragraphs":["Art. 33. A pessoa física ou entidade privada que detiver informações em virtude de vínculo de qualquer natureza com o poder público e deixar de observar o disposto nesta Lei estará sujeita às seguintes sanções:","I - advertência;","II - multa;","III - rescisão do vínculo com o poder público;","IV - suspensão temporária de participar em licitação e impedimento de contratar com a administração pública por prazo não superior a 2 (dois) anos; e","V - declaração de inidoneidade para licitar ou contratar com a administração pública, até que seja promovida a reabilitação perante a própria autoridade que aplicou a penalidade.","§ 1º As sanções previstas nos incisos I, III e IV poderão ser aplicadas juntamente com a do inciso II, assegurado o direito de defesa do interessado, no respectivo processo, no prazo de 10 (dez) dias.","§ 2º A reabilitação referida no inciso V será autorizada somente quando o interessado efetivar o ressarcimento ao órgão ou entidade dos prejuízos resultantes e após decorrido o prazo da sanção aplicada com base no inciso IV.","§ 3º A aplicação da sanção prevista no inciso V é de competência exclusiva da autoridade máxima do órgão ou entidade pública, facultada a defesa do interessado, no respectivo processo, no prazo de 10 (dez) dias da abertura de vista."],"url":""},{"key":"l12527:21","law":"l12527","ref":"21","label":"Lei de Acesso à Informação · Art. 21","paragraphs":["Art. 21. Não poderá ser negado acesso à informação necessária à tutela judicial ou administrativa de direitos fundamentais.","Parágrafo único. As informações ou documentos que versem sobre condutas que impliquem violação dos direitos humanos praticada por agentes públicos ou a mando de autoridades públicas não poderão ser objeto de restrição de acesso."],"url":""},{"key":"l12527:22","law":"l12527","ref":"22","label":"Lei de Acesso à Informação · Art. 22","paragraphs":["Art. 22. O disposto nesta Lei não exclui as demais hipóteses legais de sigilo e de segredo de justiça nem as hipóteses de segredo industrial decorrentes da exploração direta de atividade econômica pelo Estado ou por pessoa física ou entidade privada que tenha qualquer vínculo com o poder público."],"url":""},{"key":"l12527:24","law":"l12527","ref":"24","label":"Lei de Acesso à Informação · Art. 24","paragraphs":["Art. 24. A informação em poder dos órgãos e entidades públicas, observado o seu teor e em razão de sua imprescindibilidade à segurança da sociedade ou do Estado, poderá ser classificada como ultrassecreta, secreta ou reservada.","§ 1º Os prazos máximos de restrição de acesso à informação, conforme a classificação prevista no caput, vigoram a partir da data de sua produção e são os seguintes:","I - ultrassecreta: 25 (vinte e cinco) anos;","II - secreta: 15 (quinze) anos; e","III - reservada: 5 (cinco) anos.","§ 2º As informações que puderem colocar em risco a segurança do Presidente e Vice-Presidente da República e respectivos cônjuges e filhos (as) serão classificadas como reservadas e ficarão sob sigilo até o término do mandato em exercício ou do último mandato, em caso de reeleição.","§ 3º Alternativamente aos prazos previstos no § 1º, poderá ser estabelecida como termo final de restrição de acesso a ocorrência de determinado evento, desde que este ocorra antes do transcurso do prazo máximo de classificação.","§ 4º Transcorrido o prazo de classificação ou consumado o evento que defina o seu termo final, a informação tornar-se-á, automaticamente, de acesso público.","§ 5º Para a classificação da informação em determinado grau de sigilo, deverá ser observado o interesse público da informação e utilizado o critério menos restritivo possível, considerados:","I - a gravidade do risco ou dano à segurança da sociedade e do Estado; e","II - o prazo máximo de restrição de acesso ou o evento que defina seu termo final."],"url":""},{"key":"l12527:35","law":"l12527","ref":"35","label":"Lei de Acesso à Informação · Art. 35","paragraphs":["Art. 35. (VETADO).","§ 1º É instituída a Comissão Mista de Reavaliação de Informações, que decidirá, no âmbito da administração pública federal, sobre o tratamento e a classificação de informações sigilosas e terá competência para:","I - requisitar da autoridade que classificar informação como ultrassecreta e secreta esclarecimento ou conteúdo, parcial ou integral da informação;","II - rever a classificação de informações ultrassecretas ou secretas, de ofício ou mediante provocação de pessoa interessada, observado o disposto no art. 7o e demais dispositivos desta Lei; e","III - prorrogar o prazo de sigilo de informação classificada como ultrassecreta, sempre por prazo determinado, enquanto o seu acesso ou divulgação puder ocasionar ameaça externa à soberania nacional ou à integridade do território nacional ou grave risco às relações internacionais do País, observado o prazo previsto no § 1º do art. 24.","§ 2º O prazo referido no inciso III é limitado a uma única renovação.","§ 3º A revisão de ofício a que se refere o inciso II do § 1º deverá ocorrer, no máximo, a cada 4 (quatro) anos, após a reavaliação prevista no art. 39, quando se tratar de documentos ultrassecretos ou secretos.","§ 4º A não deliberação sobre a revisão pela Comissão Mista de Reavaliação de Informações nos prazos previstos no § 3º implicará a desclassificação automática das informações.","§ 5º Regulamento disporá sobre a composição, organização e funcionamento da Comissão Mista de Reavaliação de Informações, observado o mandato de 2 (dois) anos para seus integrantes e demais disposições desta Lei."],"url":""},{"key":"l12527:27","law":"l12527","ref":"27","label":"Lei de Acesso à Informação · Art. 27","paragraphs":["Art. 27. A classificação do sigilo de informações no âmbito da administração pública federal é de competência:","I - no grau de ultrassecreto, das seguintes autoridades:","a) Presidente da República;","b) Vice-Presidente da República;","c) Ministros de Estado e autoridades com as mesmas prerrogativas;","d) Comandantes da Marinha, do Exército e da Aeronáutica; e","e) Chefes de Missões Diplomáticas e Consulares permanentes no exterior;","II - no grau de secreto, das autoridades referidas no inciso I, dos titulares de autarquias, fundações ou empresas públicas e sociedades de economia mista; e","III - no grau de reservado, das autoridades referidas nos incisos I e II e das que exerçam funções de direção, comando ou chefia, nível DAS 101.5, ou superior, do Grupo-Direção e Assessoramento Superiores, ou de hierarquia equivalente, de acordo com regulamentação específica de cada órgão ou entidade, observado o disposto nesta Lei.","§ 1º A competência prevista nos incisos I e II, no que se refere à classificação como ultrassecreta e secreta, poderá ser delegada pela autoridade responsável a agente público, inclusive em missão no exterior, vedada a subdelegação.","§ 2º A classificação de informação no grau de sigilo ultrassecreto pelas autoridades previstas nas alíneas \"d\" e \"e\" do inciso I deverá ser ratificada pelos respectivos Ministros de Estado, no prazo previsto em regulamento.","§ 3º A autoridade ou outro agente público que classificar informação como ultrassecreta deverá encaminhar a decisão de que trata o art. 28 à Comissão Mista de Reavaliação de Informações, a que se refere o art. 35, no prazo previsto em regulamento."],"url":""},{"key":"l12527:32","law":"l12527","ref":"32","label":"Lei de Acesso à Informação · Art. 32","paragraphs":["Art. 32. Constituem condutas ilícitas que ensejam responsabilidade do agente público ou militar:","I - recusar-se a fornecer informação requerida nos termos desta Lei, retardar deliberadamente o seu fornecimento ou fornecê-la intencionalmente de forma incorreta, incompleta ou imprecisa;","II - utilizar indevidamente, bem como subtrair, destruir, inutilizar, desfigurar, alterar ou ocultar, total ou parcialmente, informação que se encontre sob sua guarda ou a que tenha acesso ou conhecimento em razão do exercício das atribuições de cargo, emprego ou função pública;","III - agir com dolo ou má-fé na análise das solicitações de acesso à informação;","IV - divulgar ou permitir a divulgação ou acessar ou permitir acesso indevido à informação sigilosa ou informação pessoal;","V - impor sigilo à informação para obter proveito pessoal ou de terceiro, ou para fins de ocultação de ato ilegal cometido por si ou por outrem;","VI - ocultar da revisão de autoridade superior competente informação sigilosa para beneficiar a si ou a outrem, ou em prejuízo de terceiros; e","VII - destruir ou subtrair, por qualquer meio, documentos concernentes a possíveis violações de direitos humanos por parte de agentes do Estado.","§ 1º Atendido o princípio do contraditório, da ampla defesa e do devido processo legal, as condutas descritas no caput serão consideradas:","I - para fins dos regulamentos disciplinares das Forças Armadas, transgressões militares médias ou graves, segundo os critérios neles estabelecidos, desde que não tipificadas em lei como crime ou contravenção penal; ou","II - para fins do disposto na Lei nº 8.112, de 11 de dezembro de 1990, e suas alterações, infrações administrativas, que deverão ser apenadas, no mínimo, com suspensão, segundo os critérios nela estabelecidos.","§ 2º Pelas condutas descritas no caput, poderá o militar ou agente público responder, também, por improbidade administrativa, conforme o disposto nas Leis nºs 1.079, de 10 de abril de 1950, e 8.429, de 2 de junho de 1992."],"url":""},{"key":"l13709:23","law":"l13709","ref":"23","label":"Lei Geral de Proteção de Dados · Art. 23","paragraphs":["Art. 23. O tratamento de dados pessoais pelas pessoas jurídicas de direito público referidas no parágrafo único do art. 1º da Lei nº 12.527, de 18 de novembro de 2011 (Lei de Acesso à Informação), deverá ser realizado para o atendimento de sua finalidade pública, na persecução do interesse público, com o objetivo de executar as competências legais ou cumprir as atribuições legais do serviço público, desde que:","I - sejam informadas as hipóteses em que, no exercício de suas competências, realizam o tratamento de dados pessoais, fornecendo informações claras e atualizadas sobre a previsão legal, a finalidade, os procedimentos e as práticas utilizadas para a execução dessas atividades, em veículos de fácil acesso, preferencialmente em seus sítios eletrônicos;","II - (VETADO); e","III - seja indicado um encarregado quando realizarem operações de tratamento de dados pessoais, nos termos do art. 39 desta Lei; e (Inciso com redação dada pela Lei nº 13.853, de 8/7/2019)","IV - (Vetado na Lei nº 13.853, de 8/7/2019)","§ 1º A autoridade nacional poderá dispor sobre as formas de publicidade das operações de tratamento.","§ 2º O disposto nesta Lei não dispensa as pessoas jurídicas mencionadas no caput deste artigo de instituir as autoridades de que trata a Lei nº 12.527, de 18 de novembro de 2011 (Lei de Acesso à Informação).","§ 3º Os prazos e procedimentos para exercício dos direitos do titular perante o Poder Público observarão o disposto em legislação específica, em especial as disposições constantes da Lei nº 9.507, de 12 de novembro de 1997 (Lei do Habeas Data), da Lei nº 9.784, de 29 de janeiro de 1999 (Lei Geral do Processo Administrativo), e da Lei nº 12.527, de 18 de novembro de 2011 (Lei de Acesso à Informação).","§ 4º Os serviços notariais e de registro exercidos em caráter privado, por delegação do Poder Público, terão o mesmo tratamento dispensado às pessoas jurídicas referidas no caput deste artigo, nos termos desta Lei.","§ 5º Os órgãos notariais e de registro devem fornecer acesso aos dados por meio eletrônico para a administração pública, tendo em vista as finalidades de que trata o caput deste artigo."],"url":""},{"key":"l13709:26","law":"l13709","ref":"26","label":"Lei Geral de Proteção de Dados · Art. 26","paragraphs":["Art. 26. O uso compartilhado de dados pessoais pelo Poder Público deve atender a finalidades específicas de execução de políticas públicas e atribuição legal pelos órgãos e pelas entidades públicas, respeitados os princípios de proteção de dados pessoais elencados no art. 6º desta Lei.","§ 1º É vedado ao Poder Público transferir a entidades privadas dados pessoais constantes de bases de dados a que tenha acesso, exceto:","I - em casos de execução descentralizada de atividade pública que exija a transferência, exclusivamente para esse fim específico e determinado, observado o disposto na Lei nº 12.527, de 18 de novembro de 2011 (Lei de Acesso à Informação);","II - (VETADO);","III - nos casos em que os dados forem acessíveis publicamente, observadas as disposições desta Lei;","IV - quando houver previsão legal ou a transferência for respaldada em contratos, convênios ou instrumentos congêneres; ou (Inciso acrescido pela Medida Provisória nº 869, de 27/12/2018, convertida na Lei nº 13.853, de 8/7/2019)","V - na hipótese de a transferência dos dados objetivar exclusivamente a prevenção de fraudes e irregularidades, ou proteger e resguardar a segurança e a integridade do titular dos dados, desde que vedado o tratamento para outras finalidades. (Inciso acrescido pela Medida Provisória nº 869, de 27/12/2018, convertida na Lei nº 13.853, de 8/7/2019)","§ 2º Os contratos e convênios de que trata o § 1º deste artigo deverão ser comunicados à autoridade nacional."],"url":""},{"key":"cf:1","law":"cf","ref":"1","label":"Constituição Federal · CF/88 · Art. 1","paragraphs":["Art. 1º A República Federativa do Brasil, formada pela união indissolúvel dos Estados e Municípios e do Distrito Federal, constitui-se em Estado democrático de direito e tem como fundamentos:","I - a soberania;","II - a cidadania;","III - a dignidade da pessoa humana;","IV - os valores sociais do trabalho e da livre iniciativa;","V - o pluralismo político.","Parágrafo único. Todo o poder emana do povo, que o exerce por meio de representantes eleitos ou diretamente, nos termos desta Constituição."],"url":""},{"key":"cf:2","law":"cf","ref":"2","label":"Constituição Federal · CF/88 · Art. 2","paragraphs":["Art. 2º São Poderes da União, independentes e harmônicos entre si, o Legislativo, o Executivo e o Judiciário."],"url":""},{"key":"cf:3","law":"cf","ref":"3","label":"Constituição Federal · CF/88 · Art. 3","paragraphs":["Art. 3º Constituem objetivos fundamentais da República Federativa do Brasil:","I - construir uma sociedade livre, justa e solidária;","II - garantir o desenvolvimento nacional;","III - erradicar a pobreza e a marginalização e reduzir as desigualdades sociais e regionais;","IV - promover o bem de todos, sem preconceitos de origem, raça, sexo, cor, idade e quaisquer outras formas de discriminação."],"url":""},{"key":"cf:4","law":"cf","ref":"4","label":"Constituição Federal · CF/88 · Art. 4","paragraphs":["Art. 4º A República Federativa do Brasil rege-se nas suas relações internacionais pelos seguintes princípios:","I - independência nacional;","II - prevalência dos direitos humanos;","III - autodeterminação dos povos;","IV - não-intervenção;","V - igualdade entre os Estados;","VI - defesa da paz;","VII - solução pacífica dos conflitos;","VIII - repúdio ao terrorismo e ao racismo;","IX - cooperação entre os povos para o progresso da humanidade;","X - concessão de asilo político.","Parágrafo único. A República Federativa do Brasil buscará a integração econômica, política, social e cultural dos povos da América Latina, visando à formação de uma comunidade latino-americana de nações."],"url":""},{"key":"cf:6","law":"cf","ref":"6","label":"Constituição Federal · CF/88 · Art. 6","paragraphs":["Art. 6º São direitos sociais a educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer, a segurança, a previdência social, a proteção à maternidade e à infância, a assistência aos desamparados, na forma desta Constituição. (Artigo com redação dada pela Emenda Constitucional nº 90, de 2015)","Parágrafo único. Todo brasileiro em situação de vulnerabilidade social terá direito a uma renda básica familiar, garantida pelo poder público em programa permanente de transferência de renda, cujas normas e requisitos de acesso serão determinados em lei, observada a legislação fiscal e orçamentária. (Parágrafo único acrescido pela Emenda Constitucional nº 114, de 2021)"],"url":""},{"key":"cf:9","law":"cf","ref":"9","label":"Constituição Federal · CF/88 · Art. 9","paragraphs":["Art. 9º É assegurado o direito de greve, competindo aos trabalhadores decidir sobre a oportunidade de exercê-lo e sobre os interesses que devam por meio dele defender.","§ 1º A lei definirá os serviços ou atividades essenciais e disporá sobre o atendimento das necessidades inadiáveis da comunidade.","§ 2º Os abusos cometidos sujeitam os responsáveis às penas da lei."],"url":""},{"key":"cf:7","law":"cf","ref":"7","label":"Constituição Federal · CF/88 · Art. 7","paragraphs":["Art. 7º São direitos dos trabalhadores urbanos e rurais, além de outros que visem à melhoria de sua condição social:","I - relação de emprego protegida contra despedida arbitrária ou sem justa causa, nos termos de lei complementar, que preverá indenização compensatória, dentre outros direitos;","II - seguro-desemprego, em caso de desemprego involuntário;","III - fundo de garantia do tempo de serviço;","IV - salário mínimo, fixado em lei, nacionalmente unificado, capaz de atender às suas necessidades vitais básicas e às de sua família com moradia, alimentação, educação, saúde, lazer, vestuário, higiene, transporte e previdência social, com reajustes periódicos que lhe preservem o poder aquisitivo, sendo vedada sua vinculação para qualquer fim;","V - piso salarial proporcional à extensão e à complexidade do trabalho;","VI - irredutibilidade do salário, salvo o disposto em convenção ou acordo coletivo;","VII - garantia de salário, nunca inferior ao mínimo, para os que percebem remuneração variável;","VIII - décimo terceiro salário com base na remuneração integral ou no valor da aposentadoria;","IX - remuneração do trabalho noturno superior à do diurno;","X - proteção do salário na forma da lei, constituindo crime sua retenção dolosa;","XI - participação nos lucros, ou resultados, desvinculada da remuneração, e, excepcionalmente, participação na gestão da empresa, conforme definido em lei;","XII - salário-família pago em razão do dependente do trabalhador de baixa renda nos termos da lei; (Inciso com redação dada pela Emenda Constitucional nº 20, de 1998)","XIII - duração do trabalho normal não superior a 8 (oito) horas diárias e 40 (quarenta) horas semanais, facultada a compensação de horários e a redução da jornada, mediante acordo ou convenção coletiva de trabalho; (Inciso com redação dada pela Emenda Constitucional nº 141, de 2026) (Vide art. 6º da Emenda Constitucional nº 141, de 2026)","XIV - jornada de seis horas para o trabalho realizado em turnos ininterruptos de revezamento, salvo negociação coletiva;","XV - repouso semanal remunerado, preferencialmente aos domingos; (Vide Emenda Constitucional nº 141, de 2026)","XVI - remuneração do serviço extraordinário superior, no mínimo, em cinqüenta por cento à do normal;","XVII - gozo de férias anuais remuneradas com, pelo menos, um terço a mais do que o salário normal;","XVIII - licença à gestante, sem prejuízo do emprego e do salário, com a duração de cento e vinte dias;","XIX - licença-paternidade, nos termos fixados em lei;","XX - proteção do mercado de trabalho da mulher, mediante incentivos específicos, nos termos da lei;","XXI - aviso prévio proporcional ao tempo de serviço, sendo no mínimo de trinta dias, nos termos da lei;","XXII - redução dos riscos inerentes ao trabalho, por meio de normas de saúde, higiene e segurança;","XXIII - adicional de remuneração para as atividades penosas, insalubres ou perigosas, na forma da lei;","XXIV - aposentadoria;","XXV - assistência gratuita aos filhos e dependentes desde o nascimento até 5 (cinco) anos de idade em creches e pré-escolas; (Inciso com redação dada pela Emenda Constitucional nº 53, de 2006)","XXVI - reconhecimento das convenções e acordos coletivos de trabalho;","XXVII - proteção em face da automação, na forma da lei;","XXVIII - seguro contra acidentes de trabalho, a cargo do empregador, sem excluir a indenização a que este está obrigado, quando incorrer em dolo ou culpa;","XXIX - ação, quanto aos créditos resultantes das relações de trabalho, com prazo prescricional de cinco anos para os trabalhadores urbanos e rurais, até o limite de dois anos após a extinção do contrato de trabalho; (Inciso com redação dada pela Emenda Constitucional nº 28, de 2000)","a) (Alínea revogada pela Emenda Constitucional nº 28, de 2000)","b) (Alínea revogada pela Emenda Constitucional nº 28, de 2000)","XXX - proibição de diferença de salários, de exercício de funções e de critério de admissão por motivo de sexo, idade, cor ou estado civil;","XXXI - proibição de qualquer discriminação no tocante a salário e critérios de admissão do trabalhador portador de deficiência;","XXXII - proibição de distinção entre trabalho manual, técnico e intelectual ou entre os profissionais respectivos;","XXXIII - proibição de trabalho noturno, perigoso ou insalubre a menores de dezoito e de qualquer trabalho a menores de dezesseis anos, salvo na condição de aprendiz, a partir de quatorze anos; (Inciso com redação dada pela Emenda Constitucional nº 20, de 1998)","XXXIV - igualdade de direitos entre o trabalhador com vínculo empregatício permanente e o trabalhador avulso.","§ 1º São assegurados à categoria dos trabalhadores domésticos os direitos previstos nos incisos IV, VI, VII, VIII, X, XIII, XV, XVI, XVII, XVIII, XIX, XXI, XXII, XXIV, XXVI, XXX, XXXI e XXXIII e, atendidas as condições estabelecidas em lei e observada a simplificação do cumprimento das obrigações tributárias, principais e acessórias, decorrentes da relação de trabalho e suas peculiaridades, os previstos nos incisos I, II, III, IX, XII, XXV e XXVIII, bem como a sua integração à previdência social. (Parágrafo único com redação dada pela Emenda Constitucional nº 72, de 2013, e transformado em § 1º pela Emenda Constitucional nº 141, de 2026)","§ 2º Excepcionalmente, convenção ou acordo coletivo de trabalho poderão, inclusive para os trabalhadores sujeitos a regimes diferenciados de trabalho estabelecidos em lei ou norma regulamentadora, estabelecer regime compensatório que assegure, na média, 2 (dois) dias de repouso semanal remunerado dentro do mês-calendário, garantido o gozo de pelo menos 1 (um) dos dias dentro do período máximo de 1 (uma) semana de trabalho. (Parágrafo acrescido pela Emenda Constitucional nº 141, de 2026)","§ 3º Lei poderá dispor sobre hipóteses e condições em que a duração do trabalho e os dias de repouso semanal remunerado poderão observar regimes diferenciados, respeitados os limites previstos nos incisos XIII, XIV e XV do caput deste artigo. (Parágrafo acrescido pela Emenda Constitucional nº 141, de 2026)"],"url":""},{"key":"cf:8","law":"cf","ref":"8","label":"Constituição Federal · CF/88 · Art. 8","paragraphs":["Art. 8º É livre a associação profissional ou sindical, observado o seguinte:","I - a lei não poderá exigir autorização do Estado para a fundação de sindicato, ressalvado o registro no órgão competente, vedadas ao poder público a interferência e a intervenção na organização sindical;","II - é vedada a criação de mais de uma organização sindical, em qualquer grau, representativa de categoria profissional ou econômica, na mesma base territorial, que será definida pelos trabalhadores ou empregadores interessados, não podendo ser inferior à área de um Município;","III - ao sindicato cabe a defesa dos direitos e interesses coletivos ou individuais da categoria, inclusive em questões judiciais ou administrativas;","IV - a assembléia geral fixará a contribuição que, em se tratando de categoria profissional, será descontada em folha, para custeio do sistema confederativo da representação sindical respectiva, independentemente da contribuição prevista em lei;","V - ninguém será obrigado a filiar-se ou a manter-se filiado a sindicato;","VI - é obrigatória a participação dos sindicatos nas negociações coletivas de trabalho;","VII - o aposentado filiado tem direito a votar e ser votado nas organizações sindicais;","VIII - é vedada a dispensa do empregado sindicalizado a partir do registro da candidatura a cargo de direção ou representação sindical e, se eleito, ainda que suplente, até um ano após o final do mandato, salvo se cometer falta grave nos termos da lei.","Parágrafo único. As disposições deste artigo aplicam-se à organização de sindicatos rurais e de colônias de pescadores, atendidas as condições que a lei estabelecer."],"url":""},{"key":"cf:10","law":"cf","ref":"10","label":"Constituição Federal · CF/88 · Art. 10","paragraphs":["Art. 10. É assegurada a participação dos trabalhadores e empregadores nos colegiados dos órgãos públicos em que seus interesses profissionais ou previdenciários sejam objeto de discussão e deliberação."],"url":""},{"key":"cf:20","law":"cf","ref":"20","label":"Constituição Federal · CF/88 · Art. 20","paragraphs":["Art. 20. São bens da União:","I - os que atualmente lhe pertencem e os que lhe vierem a ser atribuídos;","II - as terras devolutas indispensáveis à defesa das fronteiras, das fortificações e construções militares, das vias federais de comunicação e à preservação ambiental, definidas em lei;","III - os lagos, rios e quaisquer correntes de água em terrenos de seu domínio, ou que banhem mais de um Estado, sirvam de limites com outros países, ou se estendam a território estrangeiro ou dele provenham, bem como os terrenos marginais e as praias fluviais;","IV - as ilhas fluviais e lacustres nas zonas limítrofes com outros países; as praias marítimas; as ilhas oceânicas e as costeiras, excluídas, destas, as que contenham a sede de Municípios, exceto aquelas áreas afetadas ao serviço público e a unidade ambiental federal, e as referidas no art. 26, II; (Inciso com redação dada pela Emenda Constitucional nº 46, de 2005)","V - os recursos naturais da plataforma continental e da zona econômica exclusiva;","VI - o mar territorial;","VII - os terrenos de marinha e seus acrescidos;","VIII - os potenciais de energia hidráulica;","IX - os recursos minerais, inclusive os do subsolo;","X - as cavidades naturais subterrâneas e os sítios arqueológicos e pré-históricos;","XI - as terras tradicionalmente ocupadas pelos índios.","§ 1º É assegurada, nos termos da lei, à União, aos Estados, ao Distrito Federal e aos Municípios a participação no resultado da exploração de petróleo ou gás natural, de recursos hídricos para fins de geração de energia elétrica e de outros recursos minerais no respectivo território, plataforma continental, mar territorial ou zona econômica exclusiva, ou compensação financeira por essa exploração. (Parágrafo com redação dada pela Emenda Constitucional nº 102, de 2019, publicada no DOU de 27/9/2019, produzindo efeitos a partir da execução orçamentária do exercício financeiro subsequente)","§ 2º A faixa de até cento e cinqüenta quilômetros de largura, ao longo das fronteiras terrestres, designada como faixa de fronteira, é considerada fundamental para defesa do território nacional, e sua ocupação e utilização serão reguladas em lei."],"url":""},{"key":"cf:11","law":"cf","ref":"11","label":"Constituição Federal · CF/88 · Art. 11","paragraphs":["Art. 11. Nas empresas de mais de duzentos empregados, é assegurada a eleição de um representante destes com a finalidade exclusiva de promover-lhes o entendimento direto com os empregadores."],"url":""},{"key":"cf:12","law":"cf","ref":"12","label":"Constituição Federal · CF/88 · Art. 12","paragraphs":["Art. 12. São brasileiros:","I - natos:","a) os nascidos na República Federativa do Brasil, ainda que de pais estrangeiros, desde que estes não estejam a serviço de seu país;","b) os nascidos no estrangeiro, de pai brasileiro ou de mãe brasileira, desde que qualquer deles esteja a serviço da República Federativa do Brasil;","c) os nascidos no estrangeiro de pai brasileiro ou de mãe brasileira, desde que sejam registrados em repartição brasileira competente ou venham a residir na República Federativa do Brasil e optem, em qualquer tempo, depois de atingida a maioridade, pela nacionalidade brasileira; (Alínea com redação dada pela Emenda Constitucional nº 54, de 2007)","II - naturalizados:","a) os que, na forma da lei, adquiram a nacionalidade brasileira, exigidas aos originários de países de língua portuguesa apenas residência por um ano ininterrupto e idoneidade moral;","b) os estrangeiros de qualquer nacionalidade residentes na República Federativa do Brasil há mais de quinze anos ininterruptos e sem condenação penal, desde que requeiram a nacionalidade brasileira. (Alínea com redação dada pela Emenda Constitucional de Revisão nº 3, de 1994)","§ 1º Aos portugueses com residência permanente no País, se houver reciprocidade em favor dos brasileiros, serão atribuídos os direitos inerentes ao brasileiro, salvo os casos previstos nesta Constituição. (Parágrafo com redação dada pela Emenda Constitucional de Revisão nº 3, de 1994)","§ 2º A lei não poderá estabelecer distinção entre brasileiros natos e naturalizados, salvo nos casos previstos nesta Constituição.","§ 3º São privativos de brasileiro nato os cargos:","I - de Presidente e Vice-Presidente da República;","II - de Presidente da Câmara dos Deputados;","III - de Presidente do Senado Federal;","IV - de Ministro do Supremo Tribunal Federal;","V - da carreira diplomática;","VI - de oficial das Forças Armadas;","VII - de Ministro de Estado da Defesa. (Inciso acrescido pela Emenda Constitucional nº 23, de 1999)","§ 4º Será declarada a perda da nacionalidade do brasileiro que:","I - tiver cancelada sua naturalização, por sentença judicial, em virtude de fraude relacionada ao processo de naturalização ou de atentado contra a ordem constitucional e o Estado Democrático; (Inciso com redação dada pela Emenda Constitucional nº 131, de 2023)","II - fizer pedido expresso de perda da nacionalidade brasileira perante autoridade brasileira competente, ressalvadas situações que acarretem apatridia. (Inciso com redação dada pela Emenda Constitucional nº 131, de 2023)","a) (Alínea acrescida pela Emenda Constitucional de Revisão nº 3, de 1994, e revogada pela Emenda Constitucional nº 131, de 2023)","b) (Alínea acrescida pela Emenda Constitucional de Revisão nº 3, de 1994, e revogada pela Emenda Constitucional nº 131, de 2023)","§ 5º A renúncia da nacionalidade, nos termos do inciso II do § 4º deste artigo, não impede o interessado de readquirir sua nacionalidade brasileira originária, nos termos da lei. (Parágrafo acrescido pela Emenda Constitucional nº 131, de 2023)"],"url":""},{"key":"cf:13","law":"cf","ref":"13","label":"Constituição Federal · CF/88 · Art. 13","paragraphs":["Art. 13. A língua portuguesa é o idioma oficial da República Federativa do Brasil.","§ 1º São símbolos da República Federativa do Brasil a bandeira, o hino, as armas e o selo nacionais.","§ 2º Os Estados, o Distrito Federal e os Municípios poderão ter símbolos próprios."],"url":""},{"key":"cf:14","law":"cf","ref":"14","label":"Constituição Federal · CF/88 · Art. 14","paragraphs":["Art. 14. A soberania popular será exercida pelo sufrágio universal e pelo voto direto e secreto, com valor igual para todos, e, nos termos da lei, mediante:","I - plebiscito;","II - referendo;","III - iniciativa popular.","§ 1º O alistamento eleitoral e o voto são:","I - obrigatórios para os maiores de dezoito anos;","II - facultativos para:","a) os analfabetos;","b) os maiores de setenta anos;","c) os maiores de dezesseis e menores de dezoito anos.","§ 2º Não podem alistar-se como eleitores os estrangeiros e, durante o período do serviço militar obrigatório, os conscritos.","§ 3º São condições de elegibilidade, na forma da lei:","I - a nacionalidade brasileira;","II - o pleno exercício dos direitos políticos;","III - o alistamento eleitoral;","IV - o domicílio eleitoral na circunscrição;","V - a filiação partidária;","VI - a idade mínima de:","a) trinta e cinco anos para Presidente e Vice-Presidente da República e Senador;","b) trinta anos para Governador e Vice-Governador de Estado e do Distrito Federal;","c) vinte e um anos para Deputado Federal, Deputado Estadual ou Distrital, Prefeito, Vice-Prefeito e juiz de paz;","d) dezoito anos para Vereador.","§ 4º São inelegíveis os inalistáveis e os analfabetos.","§ 5º O Presidente da República, os Governadores de Estado e do Distrito Federal, os Prefeitos e quem os houver sucedido ou substituído no curso dos mandatos poderão ser reeleitos para um único período subseqüente. (Parágrafo com redação dada pela Emenda Constitucional nº 16, de 1997)","§ 6º Para concorrerem a outros cargos, o Presidente da República, os Governadores de Estado e do Distrito Federal e os Prefeitos devem renunciar aos respectivos mandatos até seis meses antes do pleito.","§ 7º São inelegíveis, no território de jurisdição do titular, o cônjuge e os parentes consangüíneos ou afins, até o segundo grau ou por adoção, do Presidente da República, de Governador de Estado ou Território, do Distrito Federal, de Prefeito ou de quem os haja substituído dentro dos seis meses anteriores ao pleito, salvo se já titular de mandato eletivo e candidato à reeleição.","§ 8º O militar alistável é elegível, atendidas as seguintes condições:","I - se contar menos de dez anos de serviço, deverá afastar-se da atividade;","II - se contar mais de dez anos de serviço, será agregado pela autoridade superior e, se eleito, passará automaticamente, no ato da diplomação, para a inatividade.","§ 9º Lei complementar estabelecerá outros casos de inelegibilidade e os prazos de sua cessação, a fim de proteger a probidade administrativa, a moralidade para o exercício do mandato, considerada a vida pregressa do candidato, e a normalidade e legitimidade das eleições contra a influência do poder econômico ou o abuso do exercício de função, cargo ou emprego na administração direta ou indireta. (Parágrafo com redação dada pela Emenda Constitucional de Revisão nº 4, de 1994)","§ 10. O mandato eletivo poderá ser impugnado ante a Justiça Eleitoral no prazo de quinze dias contados da diplomação, instruída a ação com provas de abuso do poder econômico, corrupção ou fraude.","§ 11. A ação de impugnação de mandato tramitará em segredo de justiça, respondendo o autor, na forma da lei, se temerária ou de manifesta má-fé.","§ 12. Serão realizadas concomitantemente às eleições municipais as consultas populares sobre questões locais aprovadas pelas Câmaras Municipais e encaminhadas à Justiça Eleitoral até 90 (noventa) dias antes da data das eleições, observados os limites operacionais relativos ao número de quesitos. (Parágrafo acrescido pela Emenda Constitucional nº 111, de 2021)","§ 13. As manifestações favoráveis e contrárias às questões submetidas às consultas populares nos termos do § 12 ocorrerão durante as campanhas eleitorais, sem a utilização de propaganda gratuita no rádio e na televisão. (Parágrafo acrescido pela Emenda Constitucional nº 111, de 2021)"],"url":""},{"key":"cf:15","law":"cf","ref":"15","label":"Constituição Federal · CF/88 · Art. 15","paragraphs":["Art. 15. É vedada a cassação de direitos políticos, cuja perda ou suspensão só se dará nos casos de:","I - cancelamento da naturalização por sentença transitada em julgado;","II - incapacidade civil absoluta;","III - condenação criminal transitada em julgado, enquanto durarem seus efeitos;","IV - recusa de cumprir obrigação a todos imposta ou prestação alternativa, nos termos do art. 5º, VIII;","V - improbidade administrativa, nos termos do art. 37, § 4º."],"url":""},{"key":"cf:16","law":"cf","ref":"16","label":"Constituição Federal · CF/88 · Art. 16","paragraphs":["Art. 16. A lei que alterar o processo eleitoral entrará em vigor na data de sua publicação, não se aplicando à eleição que ocorra até um ano da data de sua vigência. (Artigo com redação dada pela Emenda Constitucional nº 4, de 1993)"],"url":""},{"key":"cf:17","law":"cf","ref":"17","label":"Constituição Federal · CF/88 · Art. 17","paragraphs":["Art. 17. É livre a criação, fusão, incorporação e extinção de partidos políticos, resguardados a soberania nacional, o regime democrático, o pluripartidarismo, os direitos fundamentais da pessoa humana e observados os seguintes preceitos:","I - caráter nacional;","II - proibição de recebimento de recursos financeiros de entidade ou governo estrangeiros ou de subordinação a estes;","III - prestação de contas à Justiça Eleitoral;","IV - funcionamento parlamentar de acordo com a lei.","§ 1º É assegurada aos partidos políticos autonomia para definir sua estrutura interna e estabelecer regras sobre escolha, formação e duração de seus órgãos permanentes e provisórios e sobre sua organização e funcionamento e para adotar os critérios de escolha e o regime de suas coligações nas eleições majoritárias, vedada a sua celebração nas eleições proporcionais, sem obrigatoriedade de vinculação entre as candidaturas em âmbito nacional, estadual, distrital ou municipal, devendo seus estatutos estabelecer normas de disciplina e fidelidade partidária. (Parágrafo com redação dada pela Emenda Constitucional nº 97, de 2017)","§ 2º Os partidos políticos, após adquirirem personalidade jurídica, na forma da lei civil, registrarão seus estatutos no Tribunal Superior Eleitoral.","§ 3º Somente terão direito a recursos do fundo partidário e acesso gratuito ao rádio e à televisão, na forma da lei, os partidos políticos que alternativamente: (Parágrafo com redação dada pela Emenda Constitucional nº 97, de 2017)","I - obtiverem, nas eleições para a Câmara dos Deputados, no mínimo, 3% (três por cento) dos votos válidos, distribuídos em pelo menos um terço das unidades da Federação, com um mínimo de 2% (dois por cento) dos votos válidos em cada uma delas; ou (Inciso acrescido pela Emenda Constitucional nº 97, de 2017)","II - tiverem elegido pelo menos quinze Deputados Federais distribuídos em pelo menos um terço das unidades da Federação. (Inciso acrescido pela Emenda Constitucional nº 97, de 2017)","§ 4º É vedada a utilização pelos partidos políticos de organização paramilitar.","§ 5º Ao eleito por partido que não preencher os requisitos previstos no § 3º deste artigo é assegurado o mandato e facultada a filiação, sem perda do mandato, a outro partido que os tenha atingido, não sendo essa filiação considerada para fins de distribuição dos recursos do fundo partidário e de acesso gratuito ao tempo de rádio e de televisão. (Parágrafo acrescido pela Emenda Constitucional nº 97, de 2017)","§ 6º Os Deputados Federais, os Deputados Estaduais, os Deputados Distritais e os Vereadores que se desligarem do partido pelo qual tenham sido eleitos perderão o mandato, salvo nos casos de anuência do partido ou de outras hipóteses de justa causa estabelecidas em lei, não computada, em qualquer caso, a migração de partido para fins de distribuição de recursos do fundo partidário ou de outros fundos públicos e de acesso gratuito ao rádio e à televisão. (Parágrafo acrescido pela Emenda Constitucional nº 111, de 2021)","§ 7º Os partidos políticos devem aplicar no mínimo 5% (cinco por cento) dos recursos do fundo partidário na criação e na manutenção de programas de promoção e difusão da participação política das mulheres, de acordo com os interesses intrapartidários. (Parágrafo acrescido pela Emenda Constitucional nº 117, de 2022)","§ 8º O montante do Fundo Especial de Financiamento de Campanha e da parcela do fundo partidário destinada a campanhas eleitorais, bem como o tempo de propaganda gratuita no rádio e na televisão a ser distribuído pelos partidos às respectivas candidatas, deverão ser de no mínimo 30% (trinta por cento), proporcional ao número de candidatas, e a distribuição deverá ser realizada conforme critérios definidos pelos respectivos órgãos de direção e pelas normas estatutárias, considerados a autonomia e o interesse partidário. (Parágrafo acrescido pela Emenda Constitucional nº 117, de 2022)","§ 9º Dos recursos oriundos do Fundo Especial de Financiamento de Campanha e do fundo partidário destinados às campanhas eleitorais, os partidos políticos devem, obrigatoriamente, aplicar 30% (trinta por cento) em candidaturas de pessoas pretas e pardas, nas circunscrições que melhor atendam aos interesses e às estratégias partidárias. (Parágrafo acrescido pela Emenda Constitucional nº 133, de 2024, aplicando-se a partir das eleições de 2024)"],"url":""},{"key":"cf:18","law":"cf","ref":"18","label":"Constituição Federal · CF/88 · Art. 18","paragraphs":["Art. 18. A organização político-administrativa da República Federativa do Brasil compreende a União, os Estados, o Distrito Federal e os Municípios, todos autônomos, nos termos desta Constituição.","§ 1º Brasília é a Capital Federal.","§ 2º Os Territórios Federais integram a União, e sua criação, transformação em Estado ou reintegração ao Estado de origem serão reguladas em lei complementar.","§ 3º Os Estados podem incorporar-se entre si, subdividir-se ou desmembrar-se para se anexarem a outros, ou formarem novos Estados ou Territórios Federais, mediante aprovação da população diretamente interessada, através de plebiscito, e do Congresso Nacional, por lei complementar.","§ 4º A criação, a incorporação, a fusão e o desmembramento de Municípios, far-se-ão por lei estadual, dentro do período determinado por lei complementar federal, e dependerão de consulta prévia, mediante plebiscito, às populações dos Municípios envolvidos, após divulgação dos Estudos de Viabilidade Municipal, apresentados e publicados na forma da lei. (Parágrafo com redação dada pela Emenda Constitucional nº 15, de 1996)"],"url":""},{"key":"cf:19","law":"cf","ref":"19","label":"Constituição Federal · CF/88 · Art. 19","paragraphs":["Art. 19. É vedado à União, aos Estados, ao Distrito Federal e aos Municípios:","I - estabelecer cultos religiosos ou igrejas, subvencioná-los, embaraçar-lhes o funcionamento ou manter com eles ou seus representantes relações de dependência ou aliança, ressalvada, na forma da lei, a colaboração de interesse público;","II - recusar fé aos documentos públicos;","III - criar distinções entre brasileiros ou preferências entre si."],"url":""},{"key":"cf:18-A","law":"cf","ref":"18-A","label":"Constituição Federal · CF/88 · Art. 18-A","paragraphs":["Art. 18-A. Os atos administrativos praticados no Estado do Tocantins, decorrentes de sua instalação, entre 1º de janeiro de 1989 e 31 de dezembro de 1994, eivados de qualquer vício jurídico e dos quais decorram efeitos favoráveis para os destinatários ficam convalidados após 5 (cinco) anos, contados da data em que foram praticados, salvo comprovada má-fé. (Artigo acrescido pela Emenda Constitucional nº 110, de 2021)"],"url":""},{"key":"cf:21","law":"cf","ref":"21","label":"Constituição Federal · CF/88 · Art. 21","paragraphs":["Art. 21. Compete à União:","I - manter relações com Estados estrangeiros e participar de organizações internacionais;","II - declarar a guerra e celebrar a paz;","III - assegurar a defesa nacional;","IV - permitir, nos casos previstos em lei complementar, que forças estrangeiras transitem pelo território nacional ou nele permaneçam temporariamente;","V - decretar o estado de sítio, o estado de defesa e a intervenção federal;","VI - autorizar e fiscalizar a produção e o comércio de material bélico;","VII - emitir moeda;","VIII - administrar as reservas cambiais do País e fiscalizar as operações de natureza financeira, especialmente as de crédito, câmbio e capitalização, bem como as de seguros e de previdência privada;","IX - elaborar e executar planos nacionais e regionais de ordenação do território e de desenvolvimento econômico e social;","X - manter o serviço postal e o correio aéreo nacional;","XI - explorar, diretamente ou mediante autorização, concessão ou permissão, os serviços de telecomunicações, nos termos da lei, que disporá sobre a organização dos serviços, a criação de um órgão regulador e outros aspectos institucionais; (Inciso com redação dada pela Emenda Constitucional nº 8, de 1995)","XII - explorar, diretamente ou mediante autorização, concessão ou permissão:","a) os serviços de radiodifusão sonora e de sons e imagens; (Alínea com redação dada pela Emenda Constitucional nº 8, de 1995)","b) os serviços e instalações de energia elétrica e o aproveitamento energético dos cursos de água, em articulação com os Estados onde se situam os potenciais hidroenergéticos;","c) a navegação aérea, aeroespacial e a infra-estrutura aeroportuária;","d) os serviços de transporte ferroviário e aquaviário entre portos brasileiros e fronteiras nacionais, ou que transponham os limites de Estado ou Território;","e) os serviços de transporte rodoviário interestadual e internacional de passageiros;","f) os portos marítimos, fluviais e lacustres;","XIII - organizar e manter o Poder Judiciário, o Ministério Público do Distrito Federal e dos Territórios e a Defensoria Pública dos Territórios; (Inciso com redação dada pela Emenda Constitucional nº 69, de 2012, publicada no DOU de 30/3/2012, produzindo efeitos 120 dias após a publicação)","XIV - organizar e manter a polícia civil, a polícia penal, a polícia militar e o corpo de bombeiros militar do Distrito Federal, bem como prestar assistência financeira ao Distrito Federal para a execução de serviços públicos, por meio de fundo próprio; (Inciso com redação dada pela Emenda Constitucional nº 104, de 2019)","XV - organizar e manter os serviços oficiais de estatística, geografia, geologia e cartografia de âmbito nacional;","XVI - exercer a classificação, para efeito indicativo, de diversões públicas e de programas de rádio e televisão;","XVII - conceder anistia;","XVIII - planejar e promover a defesa permanente contra as calamidades públicas, especialmente as secas e as inundações;","XIX - instituir sistema nacional de gerenciamento de recursos hídricos e definir critérios de outorga de direitos de seu uso;","XX - instituir diretrizes para o desenvolvimento urbano, inclusive habitação, saneamento básico e transportes urbanos;","XXI - estabelecer princípios e diretrizes para o sistema nacional de viação;","XXII - executar os serviços de polícia marítima, aeroportuária e de fronteiras; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XXIII - explorar os serviços e instalações nucleares de qualquer natureza e exercer monopólio estatal sobre a pesquisa, a lavra, o enriquecimento e reprocessamento, a industrialização e o comércio de minérios nucleares e seus derivados, atendidos os seguintes princípios e condições:","a) toda atividade nuclear em território nacional somente será admitida para fins pacíficos e mediante aprovação do Congresso Nacional;","b) sob regime de permissão, são autorizadas a comercialização e a utilização de radioisótopos para pesquisa e uso agrícolas e industriais; (Alínea com redação dada pela Emenda Constitucional nº 118, de 2022)","c) sob regime de permissão, são autorizadas a produção, a comercialização e a utilização de radioisótopos para pesquisa e uso médicos; (Alínea acrescida pela Emenda Constitucional nº 49, de 2006, com redação dada pela Emenda Constitucional nº 118, de 2022)","d) a responsabilidade civil por danos nucleares independe da existência de culpa; (Primitiva alínea c renomeada pela Emenda Constitucional nº 49, de 2006)","XXIV - organizar, manter e executar a inspeção do trabalho;","XXV - estabelecer as áreas e as condições para o exercício da atividade de garimpagem, em forma associativa.","XXVI - organizar e fiscalizar a proteção e o tratamento de dados pessoais, nos termos da lei. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)"],"url":""},{"key":"cf:31","law":"cf","ref":"31","label":"Constituição Federal · CF/88 · Art. 31","paragraphs":["Art. 31. A fiscalização do Município será exercida pelo Poder Legislativo municipal, mediante controle externo, e pelos sistemas de controle interno do Poder Executivo municipal, na forma da lei.","§ 1º O controle externo da Câmara Municipal será exercido com o auxílio dos Tribunais de Contas dos Estados ou do Município ou dos Conselhos ou Tribunais de Contas dos Municípios, onde houver, vedada sua extinção, criação ou instalação. (Parágrafo com redação dada pela Emenda Constitucional nº 139, de 2026)","§ 2º O parecer prévio, emitido pelo órgão competente, sobre as contas que o Prefeito deve anualmente prestar, só deixará de prevalecer por decisão de dois terços dos membros da Câmara Municipal.","§ 3º As contas dos Municípios ficarão, durante sessenta dias, anualmente, à disposição de qualquer contribuinte, para exame e apreciação, o qual poderá questionar-lhes a legitimidade, nos termos da lei.","§ 4º É vedada a criação de tribunais, Conselhos ou órgãos de contas municipais."],"url":""},{"key":"cf:22","law":"cf","ref":"22","label":"Constituição Federal · CF/88 · Art. 22","paragraphs":["Art. 22. Compete privativamente à União legislar sobre:","I - direito civil, comercial, penal, processual, eleitoral, agrário, marítimo, aeronáutico, espacial e do trabalho;","II - desapropriação;","III - requisições civis e militares, em caso de iminente perigo e em tempo de guerra;","IV - águas, energia, informática, telecomunicações e radiodifusão;","V - serviço postal;","VI - sistema monetário e de medidas, títulos e garantias dos metais;","VII - política de crédito, câmbio, seguros e transferência de valores;","VIII - comércio exterior e interestadual;","IX - diretrizes da política nacional de transportes;","X - regime dos portos, navegação lacustre, fluvial, marítima, aérea e aeroespacial;","XI - trânsito e transporte;","XII - jazidas, minas, outros recursos minerais e metalurgia;","XIII - nacionalidade, cidadania e naturalização;","XIV - populações indígenas;","XV - emigração e imigração, entrada, extradição e expulsão de estrangeiros;","XVI - organização do sistema nacional de emprego e condições para o exercício de profissões;","XVII - organização judiciária, do Ministério Público do Distrito Federal e dos Territórios e da Defensoria Pública dos Territórios, bem como organização administrativa destes; (Inciso com redação dada pela Emenda Constitucional nº 69, de 2012, publicada no DOU de 30/3/2012, produzindo efeitos 120 dias após a publicação)","XVIII - sistema estatístico, sistema cartográfico e de geologia nacionais;","XIX - sistemas de poupança, captação e garantia da poupança popular;","XX - sistemas de consórcios e sorteios;","XXI - normas gerais de organização, efetivos, material bélico, garantias, convocação, mobilização, inatividades e pensões das polícias militares e dos corpos de bombeiros militares; (Inciso com redação dada pela Emenda Constitucional nº 103, de 2019)","XXII - competência da polícia federal e das polícias rodoviária e ferroviária federais;","XXIII - seguridade social;","XXIV - diretrizes e bases da educação nacional;","XXV - registros públicos;","XXVI - atividades nucleares de qualquer natureza;","XXVII - normas gerais de licitação e contratação, em todas as modalidades, para as administrações públicas diretas, autárquicas e fundacionais da União, Estados, Distrito Federal e Municípios, obedecido o disposto no art. 37, XXI, e para as empresas públicas e sociedades de economia mista, nos termos do art. 173, § 1º, III; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XXVIII - defesa territorial, defesa aeroespacial, defesa marítima, defesa civil e mobilização nacional;","XXIX - propaganda comercial.","XXX - proteção e tratamento de dados pessoais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","Parágrafo único. Lei complementar poderá autorizar os Estados a legislar sobre questões específicas das matérias relacionadas neste artigo."],"url":""},{"key":"cf:23","law":"cf","ref":"23","label":"Constituição Federal · CF/88 · Art. 23","paragraphs":["Art. 23. É competência comum da União, dos Estados, do Distrito Federal e dos Municípios:","I - zelar pela guarda da Constituição, das leis e das instituições democráticas e conservar o patrimônio público;","II - cuidar da saúde e assistência pública, da proteção e garantia das pessoas portadoras de deficiência;","III - proteger os documentos, as obras e outros bens de valor histórico, artístico e cultural, os monumentos, as paisagens naturais notáveis e os sítios arqueológicos;","IV - impedir a evasão, a destruição e a descaracterização de obras de arte e de outros bens de valor histórico, artístico ou cultural;","V - proporcionar os meios de acesso à cultura, à educação, à ciência, à tecnologia, à pesquisa e à inovação; (Inciso com redação dada pela Emenda Constitucional nº 85, de 2015, republicada no DOU de 3/3/2015)","VI - proteger o meio ambiente e combater a poluição em qualquer de suas formas;","VII - preservar as florestas, a fauna e a flora;","VIII - fomentar a produção agropecuária e organizar o abastecimento alimentar;","IX - promover programas de construção de moradias e a melhoria das condições habitacionais e de saneamento básico;","X - combater as causas da pobreza e os fatores de marginalização, promovendo a integração social dos setores desfavorecidos;","XI - registrar, acompanhar e fiscalizar as concessões de direitos de pesquisa e exploração de recursos hídricos e minerais em seus territórios;","XII - estabelecer e implantar política de educação para a segurança do trânsito.","Parágrafo único. Leis complementares fixarão normas para a cooperação entre a União e os Estados, o Distrito Federal e os Municípios, tendo em vista o equilíbrio do desenvolvimento e do bem-estar em âmbito nacional. (Parágrafo único com redação dada pela Emenda Constitucional nº 53, de 2006)"],"url":""},{"key":"cf:24","law":"cf","ref":"24","label":"Constituição Federal · CF/88 · Art. 24","paragraphs":["Art. 24. Compete à União, aos Estados e ao Distrito Federal legislar concorrentemente sobre:","I - direito tributário, financeiro, penitenciário, econômico e urbanístico;","II - orçamento;","III - juntas comerciais;","IV - custas dos serviços forenses;","V - produção e consumo;","VI - florestas, caça, pesca, fauna, conservação da natureza, defesa do solo e dos recursos naturais, proteção do meio ambiente e controle da poluição;","VII - proteção ao patrimônio histórico, cultural, artístico, turístico e paisagístico;","VIII - responsabilidade por dano ao meio ambiente, ao consumidor, a bens e direitos de valor artístico, estético, histórico, turístico e paisagístico;","IX - educação, cultura, ensino, desporto, ciência, tecnologia, pesquisa, desenvolvimento e inovação; (Inciso com redação dada pela Emenda Constitucional nº 85, de 2015, republicada no DOU de 3/3/2015)","X - criação, funcionamento e processo do juizado de pequenas causas;","XI - procedimentos em matéria processual;","XII - previdência social, proteção e defesa da saúde;","XIII - assistência jurídica e defensoria pública;","XIV - proteção e integração social das pessoas portadoras de deficiência;","XV - proteção à infância e à juventude;","XVI - organização, garantias, direitos e deveres das polícias civis.","§ 1º No âmbito da legislação concorrente, a competência da União limitar-se-á a estabelecer normas gerais.","§ 2º A competência da União para legislar sobre normas gerais não exclui a competência suplementar dos Estados.","§ 3º Inexistindo lei federal sobre normas gerais, os Estados exercerão a competência legislativa plena, para atender a suas peculiaridades.","§ 4º A superveniência de lei federal sobre normas gerais suspende a eficácia da lei estadual, no que lhe for contrário."],"url":""},{"key":"cf:25","law":"cf","ref":"25","label":"Constituição Federal · CF/88 · Art. 25","paragraphs":["Art. 25. Os Estados organizam-se e regem-se pelas Constituições e leis que adotarem, observados os princípios desta Constituição.","§ 1º São reservadas aos Estados as competências que não lhes sejam vedadas por esta Constituição.","§ 2º Cabe aos Estados explorar diretamente, ou mediante concessão, os serviços locais de gás canalizado, na forma da lei, vedada a edição de medida provisória para a sua regulamentação. (Parágrafo com redação dada pela Emenda Constitucional nº 5, de 1995)","§ 3º Os Estados poderão, mediante lei complementar, instituir regiões metropolitanas, aglomerações urbanas e microrregiões, constituídas por agrupamentos de Municípios limítrofes, para integrar a organização, o planejamento e a execução de funções públicas de interesse comum."],"url":""},{"key":"cf:26","law":"cf","ref":"26","label":"Constituição Federal · CF/88 · Art. 26","paragraphs":["Art. 26. Incluem-se entre os bens dos Estados:","I - as águas superficiais ou subterrâneas, fluentes, emergentes e em depósito, ressalvadas, neste caso, na forma da lei, as decorrentes de obras da União;","II - as áreas, nas ilhas oceânicas e costeiras, que estiverem no seu domínio, excluídas aquelas sob domínio da União, Municípios ou terceiros;","III - as ilhas fluviais e lacustres não pertencentes à União;","IV - as terras devolutas não compreendidas entre as da União."],"url":""},{"key":"cf:27","law":"cf","ref":"27","label":"Constituição Federal · CF/88 · Art. 27","paragraphs":["Art. 27. O número de Deputados à Assembléia Legislativa corresponderá ao triplo da representação do Estado na Câmara dos Deputados e, atingido o número de trinta e seis, será acrescido de tantos quantos forem os Deputados Federais acima de doze.","§ 1º Será de quatro anos o mandato dos Deputados Estaduais, aplicando-se-lhes as regras desta Constituição sobre sistema eleitoral, inviolabilidade, imunidades, remuneração, perda de mandato, licença, impedimentos e incorporação às Forças Armadas.","§ 2º O subsídio dos Deputados Estaduais será fixado por lei de iniciativa da Assembléia Legislativa, na razão de, no máximo, setenta e cinco por cento daquele estabelecido, em espécie, para os Deputados Federais, observado o que dispõem os arts. 39, § 4º, 57, § 7º, 150, II, 153, III, e 153, § 2º, I. (Parágrafo com redação dada pela Emenda Constitucional nº 19, de 1998)","§ 3º Compete às Assembléias Legislativas dispor sobre seu regimento interno, polícia e serviços administrativos de sua secretaria, e prover os respectivos cargos.","§ 4º A lei disporá sobre a iniciativa popular no processo legislativo estadual."],"url":""},{"key":"cf:28","law":"cf","ref":"28","label":"Constituição Federal · CF/88 · Art. 28","paragraphs":["Art. 28. A eleição do Governador e do Vice-Governador de Estado, para mandato de 4 (quatro) anos, realizar-se-á no primeiro domingo de outubro, em primeiro turno, e no último domingo de outubro, em segundo turno, se houver, do ano anterior ao do término do mandato de seus antecessores, e a posse ocorrerá em 6 de janeiro do ano subsequente, observado, quanto ao mais, o disposto no art. 77 desta Constituição. (“Caput” do artigo com redação dada pela Emenda Constitucional nº 111, de 2021) (Vide art. 5º da Emenda Constitucional nº 111, de 2021)","§ 1º Perderá o mandato o Governador que assumir outro cargo ou função na administração pública direta ou indireta, ressalvada a posse em virtude de concurso público e observado o disposto no art. 38, I, IV e V. (Parágrafo único transformado em § 1º pela Emenda Constitucional nº 19, de 1998)","§ 2º Os subsídios do Governador, do Vice-Governador e dos Secretários de Estado serão fixados por lei de iniciativa da Assembléia Legislativa, observado o que dispõem os arts. 37, XI, 39, §4º, 150, II, 153, III, e 153, § 2º, I. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)"],"url":""},{"key":"cf:29","law":"cf","ref":"29","label":"Constituição Federal · CF/88 · Art. 29","paragraphs":["Art. 29. O Município reger-se-á por lei orgânica, votada em dois turnos, com o interstício mínimo de dez dias, e aprovada por dois terços dos membros da Câmara Municipal, que a promulgará, atendidos os princípios estabelecidos nesta Constituição, na Constituição do respectivo Estado e os seguintes preceitos:","I - eleição do Prefeito, do Vice-Prefeito e dos Vereadores, para mandato de quatro anos, mediante pleito direto e simultâneo realizado em todo o País;","II - eleição do Prefeito e do Vice-Prefeito realizada no primeiro domingo de outubro do ano anterior ao término do mandato dos que devam suceder, aplicadas as regras do art. 77, no caso de Municípios com mais de duzentos mil eleitores; (Inciso com redação dada pela Emenda Constitucional nº 16, de 1997)","III - posse do Prefeito e do Vice-Prefeito no dia 1º de janeiro do ano subseqüente ao da eleição;","IV - para a composição das Câmaras Municipais, será observado o limite máximo de: (“Caput” do inciso com redação dada pela Emenda Constitucional nº 58, de 2009)","a) 9 (nove) Vereadores, nos Municípios de até 15.000 (quinze mil) habitantes; (Alínea com redação dada pela Emenda Constitucional nº 58, de 2009)","b) 11 (onze) Vereadores, nos Municípios de mais de 15.000 (quinze mil) habitantes e de até 30.000 (trinta mil) habitantes; (Alínea com redação dada pela Emenda Constitucional nº 58, de 2009)","c) 13 (treze) Vereadores, nos Municípios com mais de 30.000 (trinta mil) habitantes e de até 50.000 (cinquenta mil) habitantes; (Alínea com redação dada pela Emenda Constitucional nº 58, de 2009)","d) 15 (quinze) Vereadores, nos Municípios de mais de 50.000 (cinquenta mil) habitantes e de até 80.000 (oitenta mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","e) 17 (dezessete) Vereadores, nos Municípios de mais de 80.000 (oitenta mil) habitantes e de até 120.000 (cento e vinte mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","f) 19 (dezenove) Vereadores, nos Municípios de mais de 120.000 (cento e vinte mil) habitantes e de até 160.000 (cento e sessenta mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","g) 21 (vinte e um) Vereadores, nos Municípios de mais de 160.000 (cento e sessenta mil) habitantes e de até 300.000 (trezentos mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","h) 23 (vinte e três) Vereadores, nos Municípios de mais de 300.000 (trezentos mil) habitantes e de até 450.000 (quatrocentos e cinquenta mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","i) 25 (vinte e cinco) Vereadores, nos Municípios de mais de 450.000 (quatrocentos e cinquenta mil) habitantes e de até 600.000 (seiscentos mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","j) 27 (vinte e sete) Vereadores, nos Municípios de mais de 600.000 (seiscentos mil) habitantes e de até 750.000 (setecentos e cinquenta mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","k) 29 (vinte e nove) Vereadores, nos Municípios de mais de 750.000 (setecentos e cinquenta mil) habitantes e de até 900.000 (novecentos mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","l) 31 (trinta e um) Vereadores, nos Municípios de mais de 900.000 (novecentos mil) habitantes e de até 1.050.000 (um milhão e cinquenta mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","m) 33 (trinta e três) Vereadores, nos Municípios de mais de 1.050.000 (um milhão e cinquenta mil) habitantes e de até 1.200.000 (um milhão e duzentos mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","n) 35 (trinta e cinco) Vereadores, nos Municípios de mais de 1.200.000 (um milhão e duzentos mil) habitantes e de até 1.350.000 (um milhão e trezentos e cinquenta mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","o) 37 (trinta e sete) Vereadores, nos Municípios de 1.350.000 (um milhão e trezentos e cinquenta mil) habitantes e de até 1.500.000 (um milhão e quinhentos mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","p) 39 (trinta e nove) Vereadores, nos Municípios de mais de 1.500.000 (um milhão e quinhentos mil) habitantes e de até 1.800.000 (um milhão e oitocentos mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","q) 41 (quarenta e um) Vereadores, nos Municípios de mais de 1.800.000 (um milhão e oitocentos mil) habitantes e de até 2.400.000 (dois milhões e quatrocentos mil) habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","r) 43 (quarenta e três) Vereadores, nos Municípios de mais de 2.400.000 (dois milhões e quatrocentos mil) habitantes e de até 3.000.000 (três milhões) de habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","s) 45 (quarenta e cinco) Vereadores, nos Municípios de mais de 3.000.000 (três milhões) de habitantes e de até 4.000.000 (quatro milhões) de habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","t) 47 (quarenta e sete) Vereadores, nos Municípios de mais de 4.000.000 (quatro milhões) de habitantes e de até 5.000.000 (cinco milhões) de habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","u) 49 (quarenta e nove) Vereadores, nos Municípios de mais de 5.000.000 (cinco milhões) de habitantes e de até 6.000.000 (seis milhões) de habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","v) 51 (cinquenta e um) Vereadores, nos Municípios de mais de 6.000.000 (seis milhões) de habitantes e de até 7.000.000 (sete milhões) de habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","w) 53 (cinquenta e três) Vereadores, nos Municípios de mais de 7.000.000 (sete milhões) de habitantes e de até 8.000.000 (oito milhões) de habitantes; e (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","x) 55 (cinquenta e cinco) Vereadores, nos Municípios de mais de 8.000.000 (oito milhões) de habitantes; (Alínea acrescida pela Emenda Constitucional nº 58, de 2009)","V - subsídios do Prefeito, do Vice-Prefeito e dos Secretários Municipais fixados por lei de iniciativa da Câmara Municipal, observado o que dispõem os arts. 37, XI, 39, § 4º, 150, II, 153, III, e 153, § 2º, I; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VI - o subsídio dos Vereadores será fixado pelas respectivas Câmaras Municipais em cada legislatura para a subseqüente, observado o que dispõe esta Constituição, observados os critérios estabelecidos na respectiva Lei Orgânica e os seguintes limites máximos: (Inciso acrescido pela Emenda Constitucional nº 1, de 1992, e com nova redação dada pela Emenda Constitucional nº 25, de 2000)","a) em Municípios de até dez mil habitantes, o subsídio máximo dos Vereadores corresponderá a vinte por cento do subsídio dos Deputados Estaduais; (Alínea acrescida pela Emenda Constitucional nº 25, de 2000)","b) em Municípios de dez mil e um a cinqüenta mil habitantes, o subsídio máximo dos Vereadores corresponderá a trinta por cento do subsídio dos Deputados Estaduais; (Alínea acrescida pela Emenda Constitucional nº 25, de 2000)","c) em Municípios de cinqüenta mil e um a cem mil habitantes, o subsídio máximo dos Vereadores corresponderá a quarenta por cento do subsídio dos Deputados Estaduais; (Alínea acrescida pela Emenda Constitucional nº 25, de 2000)","d) em Municípios de cem mil e um a trezentos mil habitantes, o subsídio máximo dos Vereadores corresponderá a cinqüenta por cento do subsídio dos Deputados Estaduais; (Alínea acrescida pela Emenda Constitucional nº 25, de 2000)","e) em Municípios de trezentos mil e um a quinhentos mil habitantes, o subsídio máximo dos Vereadores corresponderá a sessenta por cento do subsídio dos Deputados Estaduais; (Alínea acrescida pela Emenda Constitucional nº 25, de 2000)","f) em Municípios de mais de quinhentos mil habitantes, o subsídio máximo dos Vereadores corresponderá a setenta e cinco por cento do subsídio dos Deputados Estaduais; (Alínea acrescida pela Emenda Constitucional nº 25, de 2000)","VII - o total da despesa com a remuneração dos vereadores não poderá ultrapassar o montante de cinco por cento da receita do município; (Inciso acrescido pela Emenda Constitucional nº 1, de 1992)","VIII - inviolabilidade dos Vereadores por suas opiniões, palavras e votos no exercício do mandato e na circunscrição do Município; (Primitivo inciso VI renumerado pela Emenda Constitucional nº 1, de 1992)","IX - proibições e incompatibilidades, no exercício da vereança, similares, no que couber, ao disposto nesta Constituição para os membros do Congresso Nacional e, na Constituição do respectivo Estado, para os membros da Assembléia Legislativa; (Primitivo inciso VII renumerado pela Emenda Constitucional nº 1, de 1992)","X - julgamento do Prefeito perante o Tribunal de Justiça; (Primitivo inciso VIII renumerado pela Emenda Constitucional nº 1, de 1992)","XI - organização das funções legislativas e fiscalizadoras da Câmara Municipal; (Primitivo inciso IX renumerado pela Emenda Constitucional nº 1, de 1992)","XII - cooperação das associações representativas no planejamento municipal; (Primitivo inciso X renumerado pela Emenda Constitucional nº 1, de 1992)","XIII - iniciativa popular de projetos de lei de interesse específico do Município, da cidade ou de bairros, através de manifestação de, pelo menos, cinco por cento do eleitorado; (Primitivo inciso XI renumerado pela Emenda Constitucional nº 1, de 1992)","XIV - perda do mandato do Prefeito, nos termos do art. 28, parágrafo único. (Primitivo inciso XII renumerado pela Emenda Constitucional nº 1, de 1992)"],"url":""},{"key":"cf:29-A","law":"cf","ref":"29-A","label":"Constituição Federal · CF/88 · Art. 29-A","paragraphs":["Art. 29-A. O total da despesa do Poder Legislativo Municipal, incluídos os subsídios dos Vereadores e os demais gastos com pessoal inativo e pensionistas, não poderá ultrapassar os seguintes percentuais, relativos ao somatório da receita tributária e das transferências previstas no § 5º do art. 153 e nos arts. 158 e 159 desta Constituição, efetivamente realizado no exercício anterior: (“Caput” do artigo acrescido pela Emenda Constitucional nº 25, de 2000, e com nova redação dada pela Emenda Constitucional nº 109, de 2021, publicada no DOU de 16/3/2021, em vigor a partir do início da primeira legislatura municipal após a data da publicação)","I - 7% (sete por cento) para Municípios com população de até 100.000 (cem mil) habitantes; (Inciso acrescido pela Emenda Constitucional nº 25, de 2000).e com nova redação dada pela Emenda Constitucional nº 58, de 2009)","II - 6% (seis por cento) para Municípios com população entre 100.000 (cem mil) e 300.000 (trezentos mil) habitantes; (Inciso acrescido pela Emenda Constitucional nº 25, de 2000).e com nova redação dada pela Emenda Constitucional nº 58, de 2009)","III - 5% (cinco por cento) para Municípios com população entre 300.001 (trezentos mil e um) e 500.000 (quinhentos mil) habitantes; (Inciso acrescido pela Emenda Constitucional nº 25, de 2000).e com nova redação dada pela Emenda Constitucional nº 58, de 2009)","IV - 4,5% (quatro inteiros e cinco décimos por cento) para Municípios com população entre 500.001 (quinhentos mil e um) e 3.000.000 (três milhões) de habitantes; (Inciso acrescido pela Emenda Constitucional nº 25, de 2000).e com nova redação dada pela Emenda Constitucional nº 58, de 2009)","V - 4% (quatro por cento) para Municípios com população entre 3.000.001 (três milhões e um) e 8.000.000 (oito milhões) de habitantes; (Inciso acrescido pela Emenda Constitucional nº 58, de 2009)","VI - 3,5% (três inteiros e cinco décimos por cento) para Municípios com população acima de 8.000.001 (oito milhões e um) habitantes. (Inciso acrescido pela Emenda Constitucional nº 58, de 2009)","§ 1º A Câmara Municipal não gastará mais de setenta por cento de sua receita com folha de pagamento, incluído o gasto com o subsídio de seus Vereadores. (Parágrafo acrescido pela Emenda Constitucional nº 25, de 2000)","§ 2º Constitui crime de responsabilidade do Prefeito Municipal:","I - efetuar repasse que supere os limites definidos neste artigo;","II - não enviar o repasse até o dia vinte de cada mês; ou","III - enviá-lo a menor em relação à proporção fixada na Lei Orçamentária. (Parágrafo acrescido pela Emenda Constitucional nº 25, de 2000)","§ 3º Constitui crime de responsabilidade do Presidente da Câmara Municipal o desrespeito ao § 1º deste artigo. (Parágrafo acrescido pela Emenda Constitucional nº 25, de 2000)"],"url":""},{"key":"cf:30","law":"cf","ref":"30","label":"Constituição Federal · CF/88 · Art. 30","paragraphs":["Art. 30. Compete aos Municípios:","I - legislar sobre assuntos de interesse local;","II - suplementar a legislação federal e a estadual no que couber;","III - instituir e arrecadar os tributos de sua competência, bem como aplicar suas rendas, sem prejuízo da obrigatoriedade de prestar contas e publicar balancetes nos prazos fixados em lei;","IV - criar, organizar e suprimir Distritos, observada a legislação estadual;","V - organizar e prestar, diretamente ou sob regime de concessão ou permissão, os serviços públicos de interesse local, incluído o de transporte coletivo, que tem caráter essencial;","VI - manter, com a cooperação técnica e financeira da União e do Estado, programas de educação infantil e de ensino fundamental; (Inciso com redação dada pela Emenda Constitucional nº 53, de 2006)","VII - prestar, com a cooperação técnica e financeira da União e do Estado, serviços de atendimento à saúde da população;","VIII - promover, no que couber, adequado ordenamento territorial, mediante planejamento e controle do uso, do parcelamento e da ocupação do solo urbano;","IX - promover a proteção do patrimônio histórico-cultural local, observada a legislação e a ação fiscalizadora federal e estadual."],"url":""},{"key":"cf:32","law":"cf","ref":"32","label":"Constituição Federal · CF/88 · Art. 32","paragraphs":["Art. 32. O Distrito Federal, vedada sua divisão em Municípios, reger-se-á por lei orgânica, votada em dois turnos com interstício mínimo de dez dias, e aprovada por dois terços da Câmara Legislativa, que a promulgará, atendidos os princípios estabelecidos nesta Constituição.","§ 1º Ao Distrito Federal são atribuídas as competências legislativas reservadas aos Estados e Municípios.","§ 2º A eleição do Governador e do Vice-Governador, observadas as regras do art. 77, e dos Deputados Distritais coincidirá com a dos Governadores e Deputados Estaduais, para mandato de igual duração.","§ 3º Aos Deputados Distritais e à Câmara Legislativa aplica-se o disposto no art. 27.","§ 4º Lei federal disporá sobre a utilização, pelo Governo do Distrito Federal, da polícia civil, da polícia penal, da polícia militar e do corpo de bombeiros militar. (Parágrafo com redação dada pela Emenda Constitucional nº 104, de 2019)"],"url":""},{"key":"cf:34","law":"cf","ref":"34","label":"Constituição Federal · CF/88 · Art. 34","paragraphs":["Art. 34. A União não intervirá nos Estados nem no Distrito Federal, exceto para:","I - manter a integridade nacional;","II - repelir invasão estrangeira ou de uma unidade da Federação em outra;","III - por termo a grave comprometimento da ordem pública;","IV - garantir o livre exercício de qualquer dos Poderes nas unidades da Federação;","V - reorganizar as finanças da unidade da Federação que:","a) suspender o pagamento da dívida fundada por mais de dois anos consecutivos, salvo motivo de força maior;","b) deixar de entregar aos Municípios receitas tributárias fixadas nesta Constituição dentro dos prazos estabelecidos em lei;","VI - prover a execução de lei federal, ordem ou decisão judicial;","VII - assegurar a observância dos seguintes princípios constitucionais:","a) forma republicana, sistema representativo e regime democrático;","b) direitos da pessoa humana;","c) autonomia municipal;","d) prestação de contas da administração pública, direta e indireta.","e) aplicação do mínimo exigido da receita resultante de impostos estaduais, compreendida a proveniente de transferências, na manutenção e desenvolvimento do ensino e nas ações e serviços públicos de saúde. (Alínea acrescida pela Emenda Constitucional nº 14, de 1996 e com nova redação dada pela Emenda Constitucional nº 29, de 2000)"],"url":""},{"key":"cf:33","law":"cf","ref":"33","label":"Constituição Federal · CF/88 · Art. 33","paragraphs":["Art. 33. A lei disporá sobre a organização administrativa e judiciária dos Territórios.","§ 1º Os Territórios poderão ser divididos em Municípios, aos quais se aplicará, no que couber, o disposto no Capítulo IV deste Título.","§ 2º As contas do Governo do Território serão submetidas ao Congresso Nacional, com parecer prévio do Tribunal de Contas da União.","§ 3º Nos Territórios Federais com mais de cem mil habitantes, além do Governador, nomeado na forma desta Constituição, haverá órgãos judiciários de primeira e segunda instâncias, membros do Ministério Público e defensores públicos federais; a lei disporá sobre as eleições para a Câmara Territorial e sua competência deliberativa."],"url":""},{"key":"l12527:5","law":"l12527","ref":"5","label":"Lei de Acesso à Informação · Art. 5","paragraphs":["Art. 5º É dever do Estado garantir o direito de acesso à informação, que será franqueada, mediante procedimentos objetivos e ágeis, de forma transparente, clara e em linguagem de fácil compreensão."],"url":""},{"key":"l12527:6","law":"l12527","ref":"6","label":"Lei de Acesso à Informação · Art. 6","paragraphs":["Art. 6º Cabe aos órgãos e entidades do poder público, observadas as normas e procedimentos específicos aplicáveis, assegurar a:","I - gestão transparente da informação, propiciando amplo acesso a ela e sua divulgação;","II - proteção da informação, garantindo-se sua disponibilidade, autenticidade e integridade; e","III - proteção da informação sigilosa e da informação pessoal, observada a sua disponibilidade, autenticidade, integridade e eventual restrição de acesso."],"url":""},{"key":"l12527:25","law":"l12527","ref":"25","label":"Lei de Acesso à Informação · Art. 25","paragraphs":["Art. 25. É dever do Estado controlar o acesso e a divulgação de informações sigilosas produzidas por seus órgãos e entidades, assegurando a sua proteção.","§ 1º O acesso, a divulgação e o tratamento de informação classificada como sigilosa ficarão restritos a pessoas que tenham necessidade de conhecê-la e que sejam devidamente credenciadas na forma do regulamento, sem prejuízo das atribuições dos agentes públicos autorizados por lei.","§ 2º O acesso à informação classificada como sigilosa cria a obrigação para aquele que a obteve de resguardar o sigilo.","§ 3º Regulamento disporá sobre procedimentos e medidas a serem adotados para o tratamento de informação sigilosa, de modo a protegê-la contra perda, alteração indevida, acesso, transmissão e divulgação não autorizados."],"url":""},{"key":"l12527:26","law":"l12527","ref":"26","label":"Lei de Acesso à Informação · Art. 26","paragraphs":["Art. 26. As autoridades públicas adotarão as providências necessárias para que o pessoal a elas subordinado hierarquicamente conheça as normas e observe as medidas e procedimentos de segurança para tratamento de informações sigilosas.","Parágrafo único. A pessoa física ou entidade privada que, em razão de qualquer vínculo com o poder público, executar atividades de tratamento de informações sigilosas adotará as providências necessárias para que seus empregados, prepostos ou representantes observem as medidas e procedimentos de segurança das informações resultantes da aplicação desta Lei."],"url":""},{"key":"l12527:28","law":"l12527","ref":"28","label":"Lei de Acesso à Informação · Art. 28","paragraphs":["Art. 28. A classificação de informação em qualquer grau de sigilo deverá ser formalizada em decisão que conterá, no mínimo, os seguintes elementos:","I - assunto sobre o qual versa a informação;","II - fundamento da classificação, observados os critérios estabelecidos no art. 24;","III - indicação do prazo de sigilo, contado em anos, meses ou dias, ou do evento que defina o seu termo final, conforme limites previstos no art. 24; e","IV - identificação da autoridade que a classificou.","Parágrafo único. A decisão referida no caput será mantida no mesmo grau de sigilo da informação classificada."],"url":""},{"key":"l12527:29","law":"l12527","ref":"29","label":"Lei de Acesso à Informação · Art. 29","paragraphs":["Art. 29. A classificação das informações será reavaliada pela autoridade classificadora ou por autoridade hierarquicamente superior, mediante provocação ou de ofício, nos termos e prazos previstos em regulamento, com vistas à sua desclassificação ou à redução do prazo de sigilo, observado o disposto no art. 24.","§ 1º O regulamento a que se refere o caput deverá considerar as peculiaridades das informações produzidas no exterior por autoridades ou agentes públicos.","§ 2º Na reavaliação a que se refere o caput, deverão ser examinadas a permanência dos motivos do sigilo e a possibilidade de danos decorrentes do acesso ou da divulgação da informação.","§ 3º Na hipótese de redução do prazo de sigilo da informação, o novo prazo de restrição manterá como termo inicial a data da sua produção."],"url":""},{"key":"l12527:30","law":"l12527","ref":"30","label":"Lei de Acesso à Informação · Art. 30","paragraphs":["Art. 30. A autoridade máxima de cada órgão ou entidade publicará, anualmente, em sítio à disposição na internet e destinado à veiculação de dados e informações administrativas, nos termos de regulamento:","I - rol das informações que tenham sido desclassificadas nos últimos 12 (doze) meses;","II - rol de documentos classificados em cada grau de sigilo, com identificação para referência futura;","III - relatório estatístico contendo a quantidade de pedidos de informação recebidos, atendidos e indeferidos, bem como informações genéricas sobre os solicitantes.","§ 1º Os órgãos e entidades deverão manter exemplar da publicação prevista no caput para consulta pública em suas sedes.","§ 2º Os órgãos e entidades manterão extrato com a lista de informações classificadas, acompanhadas da data, do grau de sigilo e dos fundamentos da classificação."],"url":""},{"key":"l12527:34","law":"l12527","ref":"34","label":"Lei de Acesso à Informação · Art. 34","paragraphs":["Art. 34. Os órgãos e entidades públicas respondem diretamente pelos danos causados em decorrência da divulgação não autorizada ou utilização indevida de informações sigilosas ou informações pessoais, cabendo a apuração de responsabilidade funcional nos casos de dolo ou culpa, assegurado o respectivo direito de regresso.","Parágrafo único. O disposto neste artigo aplica-se à pessoa física ou entidade privada que, em virtude de vínculo de qualquer natureza com órgãos ou entidades, tenha acesso a informação sigilosa ou pessoal e a submeta a tratamento indevido."],"url":""},{"key":"d7724:1","law":"d7724","ref":"1","label":"Decreto 7.724/2012 · Art. 1","paragraphs":["Art. 1º Este Decreto regulamenta, no âmbito do Poder Executivo federal, os procedimentos para a garantia do acesso à informação e para a classificação de informações sob restrição de acesso, observados grau e prazo de sigilo, conforme o disposto na Lei nº 12.527, de 18 de novembro de 2011, que dispõe sobre o acesso a informações previsto no inciso XXXIII do caput do art. 5º, no inciso II do § 3º do art. 37 e no § 2º do art. 216 da Constituição."],"url":""},{"key":"d7724:9","law":"d7724","ref":"9","label":"Decreto 7.724/2012 · Art. 9","paragraphs":["Art. 9º Os órgãos e entidades deverão criar Serviço de Informações ao Cidadão - SIC, com o objetivo de:","I - atender e orientar o público quanto ao acesso à informação;","II - informar sobre a tramitação de documentos nas unidades; e","III - receber e registrar pedidos de acesso à informação.","Parágrafo único. Compete ao SIC:","I - o recebimento do pedido de acesso e, sempre que possível, o fornecimento imediato da informação;","II - o registro do pedido de acesso em sistema eletrônico específico e a entrega de número do protocolo, que conterá a data de apresentação do pedido; e","III - o encaminhamento do pedido recebido e registrado à unidade responsável pelo fornecimento da informação, quando couber."],"url":""},{"key":"d7724:24","law":"d7724","ref":"24","label":"Decreto 7.724/2012 · Art. 24","paragraphs":["Art. 24. No caso de negativa de acesso à informação, ou às razões da negativa do acesso de que trata o caput do art. 21, desprovido o recurso pela Controladoria-Geral da União, o requerente poderá apresentar, no prazo de dez dias, contado da ciência da decisão, recurso à Comissão Mista de Reavaliação de Informações, observados os procedimentos previstos no Capítulo VI."],"url":""},{"key":"d7724:10","law":"d7724","ref":"10","label":"Decreto 7.724/2012 · Art. 10","paragraphs":["Art. 10. O SIC será instalado em unidade física identificada, de fácil acesso e aberta ao público.","§ 1º Nas unidades descentralizadas em que não houver SIC será oferecido serviço de recebimento e registro dos pedidos de acesso à informação.","§ 2º Se a unidade descentralizada não detiver a informação, o pedido será encaminhado ao SIC do órgão ou entidade central, que comunicará ao requerente o número do protocolo e a data de recebimento do pedido, a partir da qual se inicia o prazo de resposta."],"url":""},{"key":"d7724:11","law":"d7724","ref":"11","label":"Decreto 7.724/2012 · Art. 11","paragraphs":["Art. 11. Qualquer pessoa, natural ou jurídica, poderá formular pedido de acesso à informação.","§ 1º O pedido será apresentado em formulário padrão, por meio de sistema eletrônico específico ou presencialmente no SIC dos órgãos e das entidades. (Parágrafo com redação dada pelo Decreto nº 11.527, de 16/5/2023)","§ 2º O prazo de resposta será contado a partir da data de apresentação do pedido ao SIC.","§ 3º É facultado aos órgãos e entidades o recebimento de pedidos de acesso à informação por qualquer outro meio legítimo, como contato telefônico, correspondência eletrônica ou física, desde que atendidos os requisitos do art. 12.","§ 4º Na hipótese do § 3º, será enviada ao requerente comunicação com o número de protocolo e a data do recebimento do pedido pelo SIC, a partir da qual se inicia o prazo de resposta."],"url":""},{"key":"d7724:11-A","law":"d7724","ref":"11-A","label":"Decreto 7.724/2012 · Art. 11-A","paragraphs":["Art. 11-A. A Controladoria-Geral da União manterá sistema eletrônico específico, disponível na internet, para o registro e o atendimento aos pedidos de acesso à informação, de uso obrigatório pelos órgãos e pelas entidades de que trata o art. 5º.","§ 1º A obrigatoriedade de uso do sistema eletrônico de que trata o caput não exclui a possibilidade de que os órgãos e as entidades utilizem sistemas próprios para a organização dos fluxos internos de tratamento dos pedidos de acesso à informação.","§ 2º Os pedidos recebidos pelos órgãos e pelas entidades na forma do disposto no § 3º do art. 11 serão registrados no sistema eletrônico específico de que trata o caput na data do seu recebimento. (Artigo acrescido pelo Decreto nº 11.527, de 16/5/2023)"],"url":""},{"key":"d7724:12","law":"d7724","ref":"12","label":"Decreto 7.724/2012 · Art. 12","paragraphs":["Art. 12. O pedido de acesso à informação deverá conter:","I - nome do requerente;","II - número de documento de identificação válido;","III - especificação, de forma clara e precisa, da informação requerida; e","IV - endereço físico ou eletrônico do requerente, para recebimento de comunicações ou da informação requerida.","Parágrafo único. Será facultado ao requerente de acesso à informação, devidamente identificado no sistema eletrônico previsto no art. 11-A, optar pela preservação de sua identidade perante os órgãos ou as entidades demandados. (Parágrafo único acrescido pelo Decreto nº 11.527, de 16/5/2023)"],"url":""},{"key":"d7724:13","law":"d7724","ref":"13","label":"Decreto 7.724/2012 · Art. 13","paragraphs":["Art. 13. Não serão atendidos pedidos de acesso à informação:","I - genéricos;","II - desproporcionais ou desarrazoados; ou","III - que exijam trabalhos adicionais de análise, interpretação ou consolidação de dados e informações, ou serviço de produção ou tratamento de dados que não seja de competência do órgão ou entidade.","Parágrafo único. Na hipótese do inciso III do caput, o órgão ou entidade deverá, caso tenha conhecimento, indicar o local onde se encontram as informações a partir das quais o requerente poderá realizar a interpretação, consolidação ou tratamento de dados."],"url":""},{"key":"d7724:14","law":"d7724","ref":"14","label":"Decreto 7.724/2012 · Art. 14","paragraphs":["Art. 14. São vedadas exigências relativas aos motivos do pedido de acesso à informação."],"url":""},{"key":"d7724:15","law":"d7724","ref":"15","label":"Decreto 7.724/2012 · Art. 15","paragraphs":["Art. 15. Recebido o pedido e estando a informação disponível, o acesso será imediato.","§ 1º Caso não seja possível o acesso imediato, o órgão ou entidade deverá, no prazo de até vinte dias:","I - enviar a informação ao endereço físico ou eletrônico informado;","II - comunicar data, local e modo para realizar consulta à informação, efetuar reprodução ou obter certidão relativa à informação;","III - comunicar que não possui a informação ou que não tem conhecimento de sua existência;","IV - indicar, caso tenha conhecimento, o órgão ou entidade responsável pela informação ou que a detenha; ou","V - indicar as razões da negativa, total ou parcial, do acesso.","§ 2º Nas hipóteses em que o pedido de acesso demandar manuseio de grande volume de documentos, ou a movimentação do documento puder comprometer sua regular tramitação, será adotada a medida prevista no inciso II do § 1º.","§ 3º Quando a manipulação puder prejudicar a integridade da informação ou do documento, o órgão ou entidade deverá indicar data, local e modo para consulta, ou disponibilizar cópia, com certificação de que confere com o original.","§ 4º Na impossibilidade de obtenção de cópia de que trata o § 3º, o requerente poderá solicitar que, às suas expensas e sob supervisão de servidor público, a reprodução seja feita por outro meio que não ponha em risco a integridade do documento original."],"url":""},{"key":"d7724:16","law":"d7724","ref":"16","label":"Decreto 7.724/2012 · Art. 16","paragraphs":["Art. 16. O prazo para resposta do pedido poderá ser prorrogado por dez dias, mediante justificativa encaminhada ao requerente antes do término do prazo inicial de vinte dias."],"url":""},{"key":"d7724:17","law":"d7724","ref":"17","label":"Decreto 7.724/2012 · Art. 17","paragraphs":["Art. 17. Caso a informação esteja disponível ao público em formato impresso, eletrônico ou em outro meio de acesso universal, o órgão ou entidade deverá orientar o requerente quanto ao local e modo para consultar, obter ou reproduzir a informação.","Parágrafo único. Na hipótese do caput o órgão ou entidade desobriga-se do fornecimento direto da informação, salvo se o requerente declarar não dispor de meios para consultar, obter ou reproduzir a informação."],"url":""},{"key":"d7724:18","law":"d7724","ref":"18","label":"Decreto 7.724/2012 · Art. 18","paragraphs":["Art. 18. Quando o fornecimento da informação implicar reprodução de documentos, o órgão ou entidade, observado o prazo de resposta ao pedido, disponibilizará ao requerente Guia de Recolhimento da União - GRU ou documento equivalente, para pagamento dos custos dos serviços e dos materiais utilizados.","Parágrafo único. A reprodução de documentos ocorrerá no prazo de dez dias, contado da comprovação do pagamento pelo requerente ou da entrega de declaração de pobreza por ele firmada, nos termos da Lei nº 7.115, de 1983, ressalvadas hipóteses justificadas em que, devido ao volume ou ao estado dos documentos, a reprodução demande prazo superior."],"url":""},{"key":"d7724:19","law":"d7724","ref":"19","label":"Decreto 7.724/2012 · Art. 19","paragraphs":["Art. 19. Negado o pedido de acesso à informação, será enviada ao requerente, no prazo de resposta, comunicação com:","I - razões da negativa de acesso e seu fundamento legal;","II - possibilidade e prazo de recurso, com indicação da autoridade que o apreciará; e","III - possibilidade de apresentação de pedido de desclassificação da informação, quando for o caso, com indicação da autoridade classificadora que o apreciará.","§1º As razões de negativa de acesso a informação classificada indicarão o fundamento legal da classificação, a autoridade que a classificou e o código de indexação do documento classificado.","§ 2º Os órgãos e entidades disponibilizarão formulário padrão para apresentação de recurso e de pedido de desclassificação."],"url":""},{"key":"d7724:20","law":"d7724","ref":"20","label":"Decreto 7.724/2012 · Art. 20","paragraphs":["Art. 20. O acesso a documento preparatório ou informação nele contida, utilizados como fundamento de tomada de decisão ou de ato administrativo, será assegurado a partir da edição do ato ou decisão.","Parágrafo único. O Ministério da Fazenda e o Banco Central do Brasil classificarão os documentos que embasarem decisões de política econômica, tais como fiscal, tributária, monetária e regulatória."],"url":""},{"key":"d7724:21","law":"d7724","ref":"21","label":"Decreto 7.724/2012 · Art. 21","paragraphs":["Art. 21. No caso de negativa de acesso à informação ou de não fornecimento das razões da negativa do acesso, poderá o requerente apresentar recurso no prazo de dez dias, contado da ciência da decisão, à autoridade hierarquicamente superior à que adotou a decisão, que deverá apreciá-lo no prazo de cinco dias, contado da sua apresentação.","Parágrafo único. Desprovido o recurso de que trata o caput, poderá o requerente apresentar recurso no prazo de dez dias, contado da ciência da decisão, à autoridade máxima do órgão ou entidade, que deverá se manifestar em cinco dias contados do recebimento do recurso."],"url":""},{"key":"d7724:22","law":"d7724","ref":"22","label":"Decreto 7.724/2012 · Art. 22","paragraphs":["Art. 22. No caso de omissão de resposta ao pedido de acesso à informação, o requerente poderá apresentar reclamação no prazo de dez dias à autoridade de monitoramento de que trata o art. 40 da Lei nº 12.527, de 2011, que deverá se manifestar no prazo de cinco dias, contado do recebimento da reclamação.","§ 1º O prazo para apresentar reclamação começará trinta dias após a apresentação do pedido.","§ 2º A autoridade máxima do órgão ou entidade poderá designar outra autoridade que lhe seja diretamente subordinada como responsável pelo recebimento e apreciação da reclamação."],"url":""},{"key":"d7724:23","law":"d7724","ref":"23","label":"Decreto 7.724/2012 · Art. 23","paragraphs":["Art. 23. Desprovido o recurso de que trata o parágrafo único do art. 21 ou infrutífera a reclamação de que trata o art. 22, poderá o requerente apresentar recurso no prazo de dez dias, contado da ciência da decisão, à Controladoria-Geral da União, que deverá se manifestar no prazo de cinco dias, contado do recebimento do recurso.","§ 1º A Controladoria-Geral da União poderá determinar que o órgão ou entidade preste esclarecimentos.","§ 2º Provido o recurso, a Controladoria-Geral da União fixará prazo para o cumprimento da decisão pelo órgão ou entidade."],"url":""}];})(window);
